    "ui.be25b74da408": "\u062C\u062F\u064A\u062F\u0629 \u0644\u0625\u0646\u0642\u0627\u0630 \u0628\u064A\u0627\u0646\u0627\u062A \u0627\u0644\u062A\u0646\u0648\u0639 \u0627\u0644\u0628\u064A\u0648\u0644\u0648\u062C\u064A\u061F",
    "ui.327414c7f308": "\u0648\u0627\u0644\u0625\u0646\u0642\u0627\u0630 \u064A\u0639\u0646\u064A \u0627\u0644\u062D\u0641\u0627\u0638 \u0639\u0644\u0649 \u0627\u0644\u0628\u064A\u0627\u0646\u0627\u062A \u0648\u0627\u0633\u062A\u0639\u0627\u062F\u0629 \u0627\u0644\u0633\u064A\u0627\u0642 \u0627\u0644\u0630\u064A \u064A\u062C\u0639\u0644\u0647\u0627 \u0642\u0627\u0628\u0644\u0629 \u0644\u0644\u0627\u0633\u062A\u062E\u062F\u0627\u0645: \u0627\u0644\u062A\u0639\u0627\u0631\u064A\u0641 \u0648\u0627\u0644\u0648\u062D\u062F\u0627\u062A \u0627\u0644\u0645\u064A\u062F\u0627\u0646\u064A\u0629\u060C \u0648\u062C\u0647\u0648\u062F \u0623\u062E\u0630 \u0627\u0644\u0639\u064A\u0646\u0627\u062A\u060C \u0648\u0627\u0644\u0628\u0631\u0648\u062A\u0648\u0643\u0648\u0644\u0627\u062A \u0648\u0627\u0644\u0623\u062F\u0644\u0629\u060C \u0648\u0627\u0644\u0628\u062F\u0621 \u0628\u0645\u0644\u0641 \u0623\u0648 \u0645\u0645\u0627\u0631\u0633\u0629 \u0645\u0639 \u0645\u062C\u0645\u0648\u0639\u0629 \u0628\u064A\u0627\u0646\u0627\u062A \u062E\u064A\u0627\u0644\u064A\u0629 \u0642\u0627\u0628\u0644\u0629 \u0644\u0644\u062A\u062F\u0627\u0648\u0644.",
    "ui.fbd5a2c5e9f4": "\u062E\u0630 \u062C\u0648\u0644\u0629 \u062F\u0642\u064A\u0642\u062A\u064A\u0646",
