    "ui.6afc79b255ee": "\u0646\u0648\u0627\u0641\u0630 \u0627\u0644\u0642\u0631\u0627\u0621\u0629 \u0641\u0642\u0637",
    "ui.a0415123913d": "\u0648\u0647\u0646\u0627\u0643 \u0646\u0627\u0641\u0630\u0629 \u0623\u062E\u0631\u0649 \u062A\u0645\u0644\u0643 \u0633\u0644\u0637\u0629 \u062A\u062D\u0631\u064A\u0631\u060C \u0623\u0648 \u062A\u0646\u062A\u0647\u064A \u0647\u0630\u0647 \u0627\u0644\u062F\u0648\u0631\u0629\u060C \u0648\u064A\u0645\u0643\u0646 \u062A\u0641\u062A\u064A\u0634 \u0627\u0644\u0623\u0635\u0648\u0644 \u0648\u0627\u0644\u0628\u064A\u0627\u0646\u0627\u062A \u0627\u0644\u0645\u0644\u062A\u0632\u0645\u0629\u060C \u0648\u0644\u0627 \u062A\u0632\u0627\u0644 \u0647\u0646\u0627\u0643 \u0623\u0634\u0643\u0627\u0644 \u063A\u064A\u0631 \u0645\u062A\u0648\u0627\u0641\u0631\u0629.",
