    "ui.06db1c455e41": "\u0641\u0627\u0644\u0623\u0646\u0648\u0627\u0639 \u0627\u0644\u0645\u0633\u062A\u062F\u0644\u0629 \u0648\u0627\u0644\u0645\u062D\u062F\u062F\u0627\u062A \u0627\u0644\u0645\u062D\u062A\u0645\u0644\u0629 \u062A\u0635\u0641 \u0627\u0644\u0642\u064A\u0645 \u0627\u0644\u062D\u0627\u0644\u064A\u0629\u060C \u0641\u0647\u064A \u0644\u0627 \u062A\u062D\u062F\u062F \u0645\u0627 \u064A\u0639\u0646\u064A\u0647 \u0627\u0644\u062D\u0642\u0644\u060C \u0648\u0644\u0627 \u062A\u063A\u064A\u0631 \u0633\u0648\u0649 \u0647\u0630\u0627 \u0627\u0644\u0631\u0623\u064A.",
    "ui.91d9c0af87da": "(\u0628) \u0625\u0628\u0642\u0627\u0621 \u0627\u0644\u062A\u0641\u0633\u064A\u0631\u0627\u062A \u063A\u064A\u0631 \u0627\u0644\u0645\u0639\u0631\u0648\u0641\u0629 \u0648\u0627\u0644\u0645\u0633\u062A\u0648\u062D\u0627\u0629 \u0648\u0627\u0644\u0645\u062A\u0636\u0627\u0631\u0628\u0629 \u0645\u0631\u0626\u064A\u0629\u060C \u0648\u064A\u0645\u0643\u0646 \u0623\u0646 \u062A\u0643\u0648\u0646 \u0627\u0644\u0623\u062F\u0644\u0629 \u0628\u0631\u0648\u062A\u0648\u0643\u0648\u0644\u0627\u064B \u0645\u0644\u062D\u0642\u0627\u064B \u0623\u0648 \u0645\u0631\u062C\u0639\u0627\u064B \u062E\u0627\u0631\u062C\u064A\u0627\u064B\u060C \u0648\u062A\u064F\u062E\u0632\u0651\u064E\u0646 \u0627\u0644\u0645\u0631\u0627\u062C\u0639 \u0627\u0644\u062E\u0627\u0631\u062C\u064A\u0629 \u0643\u0646\u0635\u061B \u0648\u0644\u0627 \u064A\u062C\u0644\u0628\u0647\u0627 \u0627\u0644\u062A\u0637\u0628\u064A\u0642 \u0623\u0628\u062F\u0627\u064B.",
    "ui.cb98211f5ae7": "\u0641\u0627\u0644\u062A\u0642\u064A\u064A\u0645 \u0644\u0647 \u0637\u0628\u0642\u0627\u062A: \u062D\u0641\u0638 \u0627\u0644\u0645\u0644\u0641\u0627\u062A\u060C \u0648\u0627\u0644\u062C\u062F\u0648\u0644/\u0647\u064A\u0643\u0644 \u0627\u0644\u0643\u064A\u0645\u0627\u0648\u064A\u0627\u062A\u060C \u0648\u0627\u0644\u0639\u0644\u0627\u0642\u0627\u062A\u060C \u0648\u0627\u0644\u0628\u064A\u0627\u0646\u0627\u062A \u0627\u0644\u0641\u0648\u0642\u064A\u0629\u060C \u0648\u0631\u0633\u0645 \u062E\u0631\u0627\u0626\u0637 \u0627\u0644\u0645\u0639\u0627\u064A\u064A\u0631\u060C \u0648\u0639\u0644\u0627\u0645\u0627\u062A \u0627\u0644\u0625\u0646\u0630\u0627\u0631 \u0627\u0644\u0639\u0644\u0645\u064A\u060C \u0648\u0644\u0627 \u064A\u0632\u0627\u0644 \u0645\u0646 \u0627\u0644\u0645\u0645\u0643\u0646 \u0623\u0646 \u064A\u0643\u0648\u0646 \u0627\u0644\u062C\u062F\u0648\u0644 \u0627\u0644\u0635\u062D\u064A\u062D \u0645\u0646 \u0627\u0644\u0646\u0627\u062D\u064A\u0629 \u0627\u0644\u062A\u0642\u0646\u064A\u0629 \u062E\u0627\u0637\u0626\u0627 \u0645\u0646 \u0627\u0644\u0646\u0627\u062D\u064A\u0629 \u0627\u0644\u0639\u0644\u0645\u064A\u0629.",
    "ui.f5598a7daada": "\u0648\u062A\u0634\u062A\u0645\u0644 \u0645\u062C\u0645\u0648\u0639\u0629 \u062A\u062F\u0627\u0628\u064A\u0631 \u0627\u0644\u062D\u0641\u0638 \u0639\u0644\u0649 \u0623\u0635\u0648\u0644 \u0648\u0623\u062F\u0644\u0629 \u0648\u062A\u0627\u0631\u064A\u062E \u062E\u0627\u0635\u060C \u0625\u0630 \u064A\u063A\u0641\u0644 \u0627\u0644\u062C\u0645\u0647\u0648\u0631 \u062A\u0635\u062F\u064A\u0631 \u0647\u0630\u0647 \u0627\u0644\u0645\u0648\u0627\u062F \u0627\u0644\u062E\u0627\u0635\u0629 \u0648\u064A\u0646\u0633\u0642 \u0639\u0645\u0644\u064A\u0627\u062A \u0625\u0639\u0627\u062F\u0629 \u0627\u0644\u062A\u0643\u0631\u0627\u0631 \u0623\u0648 \u0627\u0644\u062A\u0642\u0631\u064A\u0628 \u0627\u0644\u0635\u0631\u064A\u062D \u0644\u0644\u0646\u0633\u062E \u0641\u0642\u0637.",
