    "ui.db6619baea84": "\u0648\u062A\u063A\u0637\u064A \u0641\u0647\u0631\u0633 \u0645\u0627 \u0642\u0628\u0644 \u0627\u0644\u0627\u0633\u062A\u0639\u0631\u0627\u0636 \u0627\u0644\u0648\u0635\u0644\u0627\u062A \u0627\u0644\u0628\u064A\u0646\u064A\u0629 \u0648\u0627\u0644\u062A\u0642\u0627\u0631\u064A\u0631 \u0648\u0627\u0644\u0645\u0635\u0627\u062F\u0642\u0629 \u0648\u0627\u0644\u062A\u062F\u0631\u064A\u0633\u060C \u0648\u0633\u0627\u0639\u062F\u062A \u0627\u0644\u062A\u0631\u062C\u0645\u0629 \u0627\u0644\u062A\u062D\u0631\u064A\u0631\u064A\u0629 \u0627\u0644\u0622\u0644\u064A\u0629 \u0627\u0644\u0645\u062D\u0644\u064A\u0629\u060C \u0648\u0644\u0627 \u062A\u0632\u0627\u0644 \u0627\u0644\u062A\u063A\u0637\u064A\u0629 \u0648\u0627\u0644\u0635\u064A\u0627\u063A\u0629 \u0642\u064A\u062F \u0627\u0644\u0627\u0633\u062A\u0639\u0631\u0627\u0636\u061B \u0648\u0644\u0645 \u062A\u0642\u062F\u0645 \u0628\u0639\u062F \u0644\u063A\u0627\u062A \u0645\u0627 \u0642\u0628\u0644 \u0627\u0644\u0627\u0633\u062A\u0639\u0631\u0627\u0636 \u0643\u0627\u0645\u0644\u0629.",
    "ui.9c52040446da": "\u064A\u0645\u0643\u0646 \u0627\u0644\u062D\u0635\u0648\u0644 \u0639\u0644\u0649 \u0622\u062E\u0631 \u0627\u0644\u0645\u0633\u062A\u062C\u062F\u0627\u062A \u0641\u064A \u0642\u0630\u064A\u0641\u0629 \u0627\u0644\u0639\u0645\u0644 \u0648\u0625\u0646\u0642\u0627\u0630 \u0643\u0644 \u0627\u0644\u0639\u0645\u0644 \u0642\u0628\u0644 \u0625\u0639\u0627\u062F\u0629 \u0627\u0644\u062A\u062D\u0645\u064A\u0644",
