    "v06.settings.Large": "\u0645\u062C\u0645\u0648\u0639\u0627\u062A \u0643\u0628\u064A\u0631\u0629 \u0645\u0646 \u0627\u0644\u0628\u064A\u0627\u0646\u0627\u062A",
