    "v062.reason": "\u0627\u0644\u0627\u062A\u0641\u0627\u0642\u064A\u0629 \u0627\u0644\u0645\u062A\u0639\u0644\u0642\u0629 \u0628\u0627\u0644\u0623\u0633\u0628\u0627\u0628 \u0648\u0628\u0627\u0644\u062F\u0639\u0645",
    "v062.confirmStatement": "\u0648\u0642\u062F \u0627\u0633\u062A\u0639\u0631\u0636\u062A \u0647\u0630\u0627 \u0627\u0644\u062A\u0641\u0633\u064A\u0631 \u0648\u062D\u062F\u0648\u062F\u0647\u060C \u0648\u0647\u0630\u0627 \u062A\u0623\u0643\u064A\u062F \u0635\u0631\u064A\u062D \u0648\u0644\u064A\u0633 \u0627\u0642\u062A\u0631\u0627\u062D\u0627 \u0622\u0644\u064A\u0627.",
    "v062.basisExplanation": "\u062A\u0623\u0643\u064A\u062F \u0635\u062D\u0629 \u0627\u0644\u0625\u0646\u0633\u0627\u0646 \u064A\u0633\u062C\u0644 \u062D\u0643\u0645\u0643\u060C \u062A\u0623\u0643\u064A\u062F \u0627\u0644\u0623\u062F\u0644\u0629 \u064A\u062A\u0637\u0644\u0628 \u0623\u064A\u0636\u0627\u064B \u0645\u0644\u0641\u0627\u064B \u0645\u062D\u062F\u062F\u0627\u064B \u0648\u0645\u0648\u0642\u0639\u0627\u064B\u060C \u0627\u0644\u062B\u0642\u0629 \u0648\u062D\u062F\u0647\u0627 \u0644\u0627 \u062A\u0624\u0643\u062F \u0645\u0639\u0646\u0649 \u0639\u0644\u0645\u064A",
