    "v062.apply": "\u0627\u0644\u062A\u0631\u062C\u0645\u0629 \u0627\u0644\u062A\u062D\u0631\u064A\u0631\u064A\u0629 \u0627\u0644\u0645\u0631\u0627\u062C\u0639\u0629 \u0627\u0644\u062A\u0637\u0628\u064A\u0642\u064A\u0629",
    "v062.cancelPreview": "\u0627\u0633\u062A\u0639\u0631\u0627\u0636 \u0623\u0648\u0644\u064A",
    "v062.previewTitle": "\u0627\u0633\u062A\u0639\u0631\u0627\u0636 \u0627\u0644\u0646\u062A\u064A\u062C\u0629 \u0627\u0644\u0645\u0642\u062A\u0631\u062D\u0629",
    "v062.previewOnly": "\u0644\u0645 \u064A\u062A\u0645 \u0625\u0646\u0642\u0627\u0630 \u0623\u064A \u0634\u064A\u0621\u060C \u0641\u0628\u062D\u062B \u0647\u0630\u0647 \u0627\u0644\u0623\u0645\u062B\u0644\u0629 \u0648\u062D\u0633\u0627\u0628\u0627\u062A \u0627\u0644\u0646\u062A\u0627\u0626\u062C \u0627\u0644\u0643\u0627\u0645\u0644\u0629 \u0642\u0628\u0644 \u0627\u0644\u062A\u0637\u0628\u064A\u0642.",
