    "v062.unresolvedPolicy": "\u0648\u062A\u062D\u062A\u0641\u0638 \u0627\u0644\u0642\u064A\u062F\u0627\u062A \u063A\u064A\u0631 \u0627\u0644\u0645\u0639\u0632\u0648\u0644\u0629 \u0648\u0627\u0644\u0645\u062A\u0636\u0627\u0631\u0628\u0629 \u0628\u0645\u062F\u062E\u0644\u0627\u062A\u0647\u0627 \u0627\u0644\u0623\u062F\u0628\u064A\u0629 \u0641\u064A \u0627\u0644\u0645\u064A\u062F\u0627\u0646 \u0627\u0644\u0645\u0633\u062A\u0645\u062F \u0648\u062A\u062A\u0644\u0642\u0649 \u0639\u0645\u0648\u062F\u0627\u064B \u0645\u0633\u062A\u0642\u0644\u0627\u064B \u0645\u0646 \u062F\u0648\u0644\u0629 \u0627\u0644\u0627\u0633\u062A\u0639\u0631\u0627\u0636\u060C \u0648\u0644\u0627 \u064A\u0632\u0627\u0644 \u0647\u0646\u0627\u0643 \u0645\u062C\u0627\u0644 \u0645\u062A\u0631\u062C\u0645 \u062C\u0632\u0626\u064A\u0627\u064B \u064A\u064F\u0633\u062A\u062F\u0644 \u0639\u0644\u064A\u0647\u061B \u0648\u0644\u0627 \u064A\u0648\u062C\u062F \u0645\u064A\u062F\u0627\u0646 \u063A\u064A\u0631 \u0645\u0643\u062A\u0645\u0644 \u0644\u0644\u0648\u062D\u062F\u0629 \u0627\u0644\u0645\u062E\u062A\u0644\u0637\u0629 \u0644\u0627 \u064A\u0624\u0643\u0651\u0650\u062F \u0648\u062D\u062F\u0629 \u0648\u0627\u062D\u062F\u0629 \u0644\u0643\u0644 \u0635\u0641.",
