    "v065.exampleBounds": "\u0648\u062A\u0638\u0647\u0631 \u0627\u0644\u0623\u0645\u062B\u0644\u0629 \u0639\u0644\u0649 \u0630\u0644\u0643 \u0641\u064A \u0623\u0643\u062B\u0631 \u0645\u0646 \u0639\u0634\u0631\u0629 \u0633\u062C\u0644\u0627\u062A \u0644\u0643\u0644 \u0646\u062A\u064A\u062C\u0629 \u0648500 \u0634\u062E\u0635\u064A\u0629 \u0644\u0643\u0644 \u0639\u0646\u0635\u0631 \u0631\u0626\u064A\u0633\u064A\u060C \u0648\u062A\u0624\u062B\u0631 \u0627\u0644\u062A\u0642\u0644\u0628\u0627\u062A \u0639\u0644\u0649 \u0627\u0644\u0639\u0631\u0636 \u0641\u0642\u0637\u061B \u0648\u062A\u062D\u062F\u062F \u0627\u0644\u0642\u064A\u0645 \u0627\u0644\u0643\u0627\u0645\u0644\u0629 \u0627\u0644\u0645\u0637\u0627\u0628\u0642\u0627\u062A \u0648\u0628\u0635\u0645\u0627\u062A \u062C\u062F\u0627\u0648\u0644 \u0627\u0644\u0639\u0645\u0644.",
