    "v066.historyCells": "\u0627\u0644\u062A\u063A\u064A\u064A\u0631\u0627\u062A \u0627\u0644\u0645\u0633\u062C\u0644\u0629 \u0641\u064A \u0627\u0644\u062E\u0644\u0627\u064A\u0627",
    "v066.previewSafety": "\u0648\u062A\u062A\u0641\u0642 \u0639\u0645\u0644\u064A\u0629 \u0625\u0639\u0627\u062F\u0629 \u0627\u0644\u0635\u064A\u0627\u063A\u0629 \u0627\u0644\u0643\u0627\u0645\u0644\u0629 \u0645\u0639 \u0637\u0627\u0648\u0644\u0629 \u0627\u0644\u0639\u0645\u0644 \u0627\u0644\u0645\u062D\u0632\u0645\u0629\u060C \u0648\u062A\u0633\u062A\u0639\u0631\u0636 \u0647\u0648\u064A\u062A\u0643 \u0648\u0633\u0628\u0628\u0643 \u0642\u0628\u0644 \u0625\u062C\u0631\u0627\u0621 \u062A\u062D\u0642\u064A\u0642 \u0645\u0633\u062A\u0642\u0644\u060C \u0648\u062A\u062D\u062A\u0641\u0638 \u0623\u062C\u0647\u0632\u0629 \u062A\u062D\u062F\u064A\u062F \u0627\u0644\u0647\u0648\u064A\u0629 \u0627\u0644\u062A\u0627\u0631\u064A\u062E\u064A\u0629 \u0628\u0646\u0637\u0627\u0642\u0647\u0627 \u0627\u0644\u0623\u0635\u0644\u064A\u060C \u0648\u0644\u0627 \u062A\u0639\u0627\u062F \u0631\u0628\u0637\u0647\u0627 \u062A\u0644\u0642\u0627\u0626\u064A\u0627.",
    "v066.ready": "\u062A\u0645 \u0627\u0644\u062A\u0635\u062F\u064A\u0642 \u0645\u0633\u0628\u0642\u0627\u064B \u0639\u0644\u0649 \u0627\u0633\u062A\u0639\u062F\u0627\u062F \u0644\u0644\u0627\u0633\u062A\u0639\u0631\u0627\u0636",
    "v066.restored": "\u062D\u0632\u0645\u0629 \u0645\u0635\u062F\u0642\u0629 \u0623\u0639\u064A\u062F\u062A \u0643\u062A\u062D\u0642\u064A\u0642 \u0645\u0646\u0641\u0635\u0644",
    "v066.verificationFailed": "\u0641\u0634\u0644 \u0627\u0644\u062A\u062D\u0642\u0642 \u0645\u0646 \u0627\u0644\u062D\u0632\u0645 \u0648\u0644\u0645 \u064A\u064F\u0633\u062A\u0631\u062C\u0639 \u0623\u064A \u062A\u062D\u0642\u064A\u0642. {detail}",
    "v066.error.LARGE_RESTORE_LIMIT": "\u0648\u062A\u062A\u062C\u0627\u0648\u0632 \u0627\u0644\u0639\u0628\u0648\u0629 \u062D\u062C\u0645 \u0627\u0644\u0627\u0633\u062A\u0631\u062F\u0627\u062F \u0627\u0644\u0645\u062F\u0639\u0648\u0645.",
    "v066.error.LARGE_RESTORE_BUSY": "\u0647\u0646\u0627\u0643 \u0639\u062F\u062F\u0627\u0646 \u0645\u0646 \u0639\u0645\u0644\u064A\u0627\u062A \u0627\u0644\u0627\u0633\u062A\u0631\u062F\u0627\u062F \u0644\u0645 \u064A\u0628\u062A \u0641\u064A\u0647\u0627 \u0628\u0639\u062F",
    "v066.error.LARGE_RESTORE_OFFSET": "\u0627\u0644\u062A\u062D\u0645\u064A\u0644 \u0623\u0648 \u0627\u0644\u0627\u062E\u062A\u0646\u0627\u0642 \u063A\u064A\u0631 \u0635\u062D\u064A\u062D\u061B \u0625\u0639\u0627\u062F\u0629 \u062A\u062D\u0645\u064A\u0644 \u0627\u0644\u0627\u0633\u062A\u0631\u062F\u0627\u062F.",
    "v066.error.LARGE_RESTORE_INCOMPLETE": "\u0627\u0644\u062A\u062D\u0645\u064A\u0644 \u063A\u064A\u0631 \u0645\u0643\u062A\u0645\u0644 \u0644\u0645 \u064A\u064F\u0633\u062A\u0631\u062C\u0639 \u0623\u064A \u062A\u062D\u0642\u064A\u0642",
    "v066.error.LARGE_RESTORE_EXPIRED": "\u0627\u0646\u0642\u0636\u062A \u0641\u062A\u0631\u0629 \u0627\u0644\u0627\u0633\u062A\u0631\u062F\u0627\u062F \u0623\u0648 \u0623\u0644\u063A\u064A\u062A \u062A\u062D\u0645\u064A\u0644 \u0627\u0644\u0637\u0631\u062F \u0648\u0627\u0644\u062A\u062D\u0642\u0642 \u0645\u0646\u0647 \u0645\u0631\u0629 \u0623\u062E\u0631\u0649",
    "v066.error.LARGE_RESTORE_PREVIEW": "\u0648\u0644\u0627 \u0628\u062F \u0645\u0646 \u0625\u062C\u0631\u0627\u0621 \u0627\u0633\u062A\u0639\u0631\u0627\u0636 \u0645\u0633\u0628\u0642 \u064A\u062C\u0631\u064A \u0627\u0644\u062A\u062D\u0642\u0642 \u0645\u0646\u0647 \u0642\u0628\u0644 \u0627\u0644\u0627\u0633\u062A\u0639\u0627\u062F\u0629.",
    "v066.error.LARGE_RESTORE_REVIEW": "\u0623\u062F\u062E\u0644\u064A \u0647\u0648\u064A\u0651\u0629 \u0627\u0644\u0627\u0633\u062A\u0639\u0631\u0627\u0636 \u0648\u0627\u0644\u0633\u0628\u0628 \u0642\u0628\u0644 \u0627\u0644\u0627\u0633\u062A\u0639\u0627\u062F\u0629.",
    "v066.error.LARGE_RESTORE_EXISTS": "\u0627\u0644\u062A\u062D\u0642\u064A\u0642 \u0627\u0644\u0645\u0633\u062A\u0647\u062F\u0641 \u0645\u0648\u062C\u0648\u062F \u0628\u0627\u0644\u0641\u0639\u0644 \u0644\u0645 \u062A\u0643\u0646 \u0647\u0646\u0627\u0643 \u0645\u0644\u0641\u0627\u062A \u0645\u0648\u062C\u0648\u062F\u0629",
    "v066.error.LARGE_RESTORE_SOURCE": "\u0627\u0644\u0623\u0635\u0644\u064A \u0627\u0644\u0645\u062D\u0645\u064A \u0644\u0627 \u064A\u0633\u062A\u0646\u0633\u062E \u0634\u0643\u0644 \u0627\u0644\u062C\u062F\u0648\u0644 \u0627\u0644\u0645\u0633\u062C\u0644",
    "v066.error.LARGE_RESTORE_METADATA": "\u0648\u0644\u0627 \u062A\u0634\u0643\u0644 \u062A\u0639\u0627\u0631\u064A\u0641 \u0627\u0644\u0628\u064A\u0627\u0646\u0627\u062A \u0627\u0644\u0648\u0635\u0641\u064A\u0629 \u0623\u0648 \u0627\u0644\u062A\u0627\u0631\u064A\u062E \u0633\u0644\u0633\u0644\u0629 \u0645\u0633\u062C\u0644\u0629 \u0635\u0627\u0644\u062D\u0629.",
    "v066.error.LARGE_RESTORE_HISTORY": "\u0627\u0644\u062A\u0633\u062C\u064A\u0644\u0627\u062A \u0627\u0644\u0645\u0633\u062C\u0644\u0629 \u0644\u0627 \u062A\u0634\u0643\u0644 \u062A\u0627\u0631\u064A\u062E\u0627\u064B \u0635\u0627\u0644\u062D\u0627\u064B \u0644\u0625\u0639\u0627\u062F\u0629 \u0627\u0644\u0644\u0639\u0628.",
    "v066.error.LARGE_RESTORE_REPLAY": "\u0627\u0644\u062A\u0644\u0627\u0639\u0628 \u0628\u0627\u0644\u0623\u0635\u0644 \u0644\u0627 \u064A\u0633\u062A\u0646\u0633\u062E \u0637\u0627\u0648\u0644\u0629 \u0627\u0644\u0639\u0645\u0644 \u0627\u0644\u0645\u062D\u0632\u0645\u0629",
    "v066.error.LARGE_RESTORE_INVALID": "\u0648\u0644\u0627 \u064A\u0645\u0643\u0646 \u0642\u0631\u0627\u0621\u0629 \u0645\u062C\u0645\u0648\u0639\u0629 \u0627\u0644\u062D\u0641\u0638 \u0623\u0648 \u0625\u0639\u0627\u062F\u0629 \u0635\u064A\u0627\u063A\u062A\u0647\u0627.",
