    "v0611.fieldReview": "\u0627\u0633\u062A\u0639\u0631\u0627\u0636 \u0627\u0644\u062A\u0631\u062C\u0645\u0629 \u0627\u0644\u0634\u0641\u0648\u064A\u0629 \u0627\u0644\u0645\u064A\u062F\u0627\u0646\u064A\u0629",
