    "v0612.needTables": "\u0627\u0633\u062A\u064A\u0631\u0627\u062F \u0639\u0644\u0649 \u0627\u0644\u0623\u0642\u0644 \u062C\u062F\u0648\u0644\u064A\u0646 \u0644\u0645\u0642\u0627\u0631\u0646\u0629 \u0633\u062C\u0644\u0627\u062A\u0647\u0645 \u0627\u0644\u0623\u062F\u0628\u064A\u0629",
