    "v0612.error.SELECTION": "\u0627\u062E\u062A\u0631 \u0627\u0644\u0645\u0641\u0627\u062A\u064A\u062D \u0627\u0644\u0635\u062D\u064A\u062D\u0629 \u0648\u0627\u0644\u0623\u0632\u0648\u0627\u062C \u0627\u0644\u0645\u064A\u062F\u0627\u0646\u064A\u0629 \u0628\u062F\u0648\u0646 \u062A\u0643\u0631\u0627\u0631 \u0646\u0641\u0633 \u0627\u0644\u0632\u0648\u062C",
