    "v0612.error.INTEGRITY": "\u0641\u0634\u0644 \u0627\u0644\u062A\u062D\u0642\u0642 \u0627\u0644\u0623\u0635\u0644\u064A \u0644\u0644\u0645\u0635\u062F\u0631\u060C \u062D\u0644 \u0642\u0636\u0627\u064A\u0627 \u0627\u0644\u062D\u0641\u0638 \u0642\u0628\u0644 \u0627\u0644\u0645\u0642\u0627\u0631\u0646\u0629.",
    "v0612.error.SOURCE": "\u0623\u064A \u0645\u0635\u062F\u0631 \u0647\u062A \u0623\u0648 \u0637\u0648\u0644 \u062B\u0627\u0646\u0648\u064A \u0645\u0641\u0642\u0648\u062F \u0623\u0648 \u063A\u064A\u0631 \u0635\u062D\u064A\u062D.",
    "v0612.error.LIMIT": "\u0648\u062A\u062A\u062C\u0627\u0648\u0632 \u0627\u0644\u0645\u0642\u0627\u0631\u0646\u0629 \u0627\u0644\u0643\u0627\u0645\u0644\u0629 \u0627\u0644\u062D\u062F\u0648\u062F \u0627\u0644\u0645\u062F\u0639\u0648\u0645\u0629\u060C \u0648\u0644\u0645 \u062A\u064F\u0646\u062A\u062C \u0623\u064A \u0646\u062A\u064A\u062C\u0629 \u062C\u0632\u0626\u064A\u0629.",
    "v0612.error.SHAPE": "\u0648\u064A\u062A\u0645\u064A\u0632 \u0627\u0644\u062C\u062F\u0648\u0644 \u0628\u062A\u0634\u0643\u064A\u0644\u0627\u062A \u0633\u062C\u0644\u064A\u0629 \u063A\u064A\u0631 \u0645\u062A\u062C\u0627\u0646\u0633\u0629 \u0623\u0648 \u0642\u064A\u0645 \u063A\u064A\u0631 \u0645\u062A\u0637\u0648\u0631\u0629.",
    "v0612.error.ORIGINS": "\u062B\u0628\u062A \u0627\u0644\u062A\u0633\u062C\u064A\u0644 \u0627\u0644\u0623\u0635\u0644\u064A \u063A\u064A\u0631 \u0635\u062D\u064A\u062D",
    "v0612.error.REPORT_LIMIT": "\u0648\u064A\u062A\u062C\u0627\u0648\u0632 \u0627\u0644\u062A\u0642\u0631\u064A\u0631 \u0627\u0644\u0643\u0627\u0645\u0644 \u0627\u0644\u062D\u062C\u0645 \u0627\u0644\u0645\u062F\u0639\u0648\u0645\u060C \u0648\u0644\u0645 \u064A\u0635\u062F\u0631 \u0623\u064A \u062A\u0642\u0631\u064A\u0631 \u062C\u0632\u0626\u064A.",
    "v0612.error.STALE": "\u062A\u063A\u064A\u0651\u0631 \u0627\u0644\u0645\u0634\u0631\u0648\u0639\u060C \u062A\u0645\u0647\u0651\u0644 \u0627\u0644\u0645\u0642\u0627\u0631\u0646\u0629 \u0645\u062C\u062F\u062F\u0627\u064B",
    "v0612.error.FAILED": "\u0648\u0644\u0645 \u064A\u0643\u0646 \u0645\u0646 \u0627\u0644\u0645\u0645\u0643\u0646 \u0627\u0633\u062A\u0643\u0645\u0627\u0644 \u0627\u0644\u0645\u0642\u0627\u0631\u0646\u0629\u060C \u0648\u0644\u0645 \u062A\u062A\u063A\u064A\u0631 \u0623\u064A \u0628\u064A\u0627\u0646\u0627\u062A.",
    "v0613.title": "\u0627\u0644\u062A\u0642\u0635\u064A\u0631 \u0641\u064A \u0627\u0644\u0645\u0639\u0627\u064A\u064A\u0631 \u0627\u0644\u0645\u062A\u0642\u062F\u0645\u0629",
    "v0613.scope": "\u0648\u062A\u0624\u062B\u0631 \u0647\u0630\u0647 \u0627\u0644\u062A\u0641\u0636\u064A\u0644\u0627\u062A \u0639\u0644\u0649 \u062F\u0641\u062A\u0631 \u062A\u062D\u0645\u064A\u0644 \u0627\u0644\u0645\u0639\u0627\u064A\u064A\u0631 \u0648\u0639\u0631\u0636 \u0627\u0644\u062A\u0642\u0627\u0631\u064A\u0631 \u0627\u0644\u062A\u0642\u0646\u064A\u0629\u060C \u0648\u0647\u064A \u0644\u0627 \u062A\u063A\u064A\u0631 \u0623\u0628\u062F\u0627\u064B \u0627\u0644\u0628\u064A\u0627\u0646\u0627\u062A \u0627\u0644\u0645\u0633\u062C\u0644\u0629 \u0623\u0648 \u0642\u0648\u0627\u0639\u062F \u0627\u0644\u062A\u0635\u062F\u064A\u0642 \u0623\u0648 \u062A\u062C\u0645\u064A\u062F \u0627\u0644\u0635\u0627\u062F\u0631\u0627\u062A.",
    "v0613.provider": "\u0627\u0644\u062A\u0642\u0635\u064A\u0631 Darwin Core \u0627\u0644\u0634\u064A\u0643\u0627\u062A",
    "v0613.provider.guide-only": "\u0627\u0644\u062A\u062F\u0642\u064A\u0642 \u0641\u064A \u0627\u0644\u0623\u062F\u0644\u0629 \u0641\u0642\u0637 (\u0642\u0635\u064A\u0631)",
    "v0613.provider.tdwg-review-2026-07": "\u0634\u064A\u0643\u0627\u062A \u0627\u0644\u062F\u0644\u064A\u0644 \u0628\u0627\u0644\u0625\u0636\u0627\u0641\u0629 \u0625\u0644\u0649 \u0645\u062B\u0628\u062A\u0629 TDWG- \u0628\u064A\u0636\u0627\u062A \u0627\u0644\u0627\u0633\u062A\u0639\u0631\u0627\u0636 \u0627\u0644\u0645\u062A\u0631\u0627\u0628\u0637\u0629",
    "v0613.reviewSafety": "The review schemas are an unratified draft. Choosing them enables local review checks for uploaded Darwin Core (\u062C) \u0644\u0627 \u062A\u062F\u0639\u064A \u0623\u0646\u0647\u0627 \u0645\u062A\u0648\u0627\u0641\u0642\u0629 \u0645\u0639 \u0627\u0644\u0645\u0635\u0627\u062F\u0642\u0629\u060C \u0648\u0644\u0627 \u064A\u0632\u0627\u0644 \u062A\u062F\u0641\u0642 \u0627\u0644\u0639\u0645\u0644 \u0627\u0644\u062A\u062D\u0636\u064A\u0631\u064A \u064A\u062A\u0637\u0644\u0628 \u0627\u0633\u062A\u0639\u0631\u0627\u0636\u0647 \u0627\u0644\u0635\u0631\u064A\u062D.",
    "v0613.technical": "\u0627\u0644\u062A\u0642\u0627\u0631\u064A\u0631 \u0627\u0644\u062A\u0642\u0646\u064A\u0629 \u0627\u0644\u0645\u0641\u062A\u0648\u062D\u0629 \u062D\u0633\u0628 \u0627\u0644\u062A\u0642\u0635\u064A\u0631",
    "v0613.technicalSafety": "\u0648\u0644\u0627 \u062A\u0632\u0627\u0644 \u062C\u0645\u064A\u0639 \u0627\u0644\u0623\u062E\u0637\u0627\u0621 \u0648\u0627\u0644\u0625\u0646\u0630\u0627\u0631\u0627\u062A \u0627\u0644\u0645\u0628\u0644\u063A \u0639\u0646\u0647\u0627 \u0645\u0631\u0626\u064A\u0629 \u0641\u0648\u0642 \u0627\u0644\u062A\u0641\u0627\u0635\u064A\u0644 \u0627\u0644\u062A\u0642\u0646\u064A\u0629\u060C \u0648\u0644\u0645 \u062A\u062A\u063A\u064A\u0631 \u0627\u0644\u062A\u0642\u0627\u0631\u064A\u0631 \u0648\u0646\u062A\u0627\u0626\u062C \u0627\u0644\u0645\u0635\u0627\u062F\u0642\u0629.",
    "v0613.openChecks": "\u0639\u0645\u0644\u064A\u0627\u062A \u0627\u0644\u062A\u062D\u0642\u0642 \u0645\u0646 \u0627\u0644\u0645\u0639\u0627\u064A\u064A\u0631 \u0627\u0644\u0645\u0641\u062A\u0648\u062D\u0629",
    "v0614.title": "\u0627\u0633\u062A\u0631\u062F\u0627\u062F \u0627\u0644\u0633\u0644\u0641\u0629",
    "v0614.cachedSafety": "\u0648\u0644\u0645 \u062A\u064F\u0633\u062A\u0631\u062C\u0639 \u0633\u0648\u0649 \u0642\u064A\u0645 \u0648\u0631\u0642\u0629 \u0627\u0644\u0639\u0645\u0644 \u0627\u0644\u0645\u062E\u0628\u0623\u0629\u060C \u0648\u0644\u0645 \u064A\u064F\u0633\u062A\u0631\u062C\u0639 \u0627\u0644\u0646\u0635 \u0648\u0627\u0644\u0635\u064A\u063A\u0629 \u0627\u0644\u0645\u062B\u0628\u062A\u0629\u061B \u0648\u064A\u0645\u0643\u0646 \u0623\u0646 \u062A\u0643\u0648\u0646 \u0627\u0644\u0646\u062A\u0627\u0626\u062C \u0627\u0644\u0645\u0623\u062E\u0648\u0630\u0629 \u0645\u0641\u0642\u0648\u062F\u0629 \u0623\u0648 \u0645\u062A\u0639\u062B\u0631\u0629.",
    "v0614.serialSafety": "\u0648\u0644\u0627 \u062A\u0632\u0627\u0644 \u0627\u0644\u062A\u0648\u0627\u0631\u064A\u062E \u0645\u0633\u0644\u0633\u0644\u0627\u062A \u0631\u0642\u0645\u064A\u0629 \u0648\u0644\u0627 \u062A\u0633\u062A\u062E\u062F\u0645 \u0646\u0638\u0627\u0645 \u0627\u0644\u062A\u0648\u0627\u0631\u064A\u062E \u0627\u0644\u0645\u0633\u062C\u0644\u0629 \u0625\u0644\u0627 \u0628\u0639\u062F \u0627\u0633\u062A\u0639\u0631\u0627\u0636 \u0643\u062A\u0627\u0628 \u0627\u0644\u0639\u0645\u0644 \u0627\u0644\u0623\u0635\u0644\u064A\u061B \u0648\u0644\u0645 \u064A\u064F\u0633\u062A\u062F\u0644 \u0645\u0646 \u0623\u064A \u062A\u0627\u0631\u064A\u062E \u062A\u0642\u0648\u064A\u0645\u064A.",
    "v0614.numericSafety": "\u0648\u062A\u0645\u062B\u0644 \u0627\u0644\u0623\u0631\u0642\u0627\u0645 \u0642\u064A\u0645\u0627 \u062B\u0646\u0627\u0626\u064A\u0629 \u0645\u0633\u062A\u0631\u062F\u0629\u060C \u0644\u0627 \u0646\u0635\u0627\u064B \u0643\u062A\u0627\u0628\u064A\u0627\u064B \u0645\u0639\u0631\u0648\u0636\u0627\u064B\u060C \u0648\u064A\u0645\u0643\u0646 \u0623\u0646 \u064A\u0643\u0648\u0646 \u0644\u0644\u0635\u064A\u063A\u0629\u060C \u0648\u0627\u0644\u0623\u0635\u0641\u0627\u0631 \u0627\u0644\u0631\u0626\u064A\u0633\u064A\u0629 \u0641\u064A \u0623\u0634\u0643\u0627\u0644 \u0627\u0644\u0639\u062F\u062F\u060C \u0648\u0627\u0644\u062E\u0644\u0627\u064A\u0627 \u0627\u0644\u0645\u062F\u0645\u062C\u0629\u060C \u0648\u0627\u0644\u0633\u062C\u0644\u0627\u062A \u0627\u0644\u062E\u0641\u064A\u0629 \u0633\u064A\u0627\u0642 \u064A\u0638\u0644 \u0641\u064A \u0627\u0644\u0623\u0635\u0644 \u062A\u0645\u0627\u0645\u0627\u064B.",
    "v0614.dateSystem": "\u0646\u0638\u0627\u0645 \u0627\u0644\u0645\u0648\u0627\u0639\u064A\u062F \u0627\u0644\u0645\u0633\u062C\u0644\u0629: {system}.",
    "v0614.sheetSummary": "! {name}: {rows} \u0627\u0644\u0635\u0641\u0648\u0641 {columns} \u0627\u0644\u0623\u0639\u0645\u062F\u0629\u061B {state}.",
