    "v062.error.TAXONOMY_REFERENCE": "\u0627\u062E\u062A\u0631 \u0645\u0631\u062C\u0639\u0627 \u0645\u062D\u0644\u064A\u0627 \u0635\u0627\u0644\u062D\u0627\u060C \u0648\u0645\u064A\u0627\u062F\u064A\u0646 \u0627\u0644\u0627\u0633\u0645 \u0627\u0644\u0645\u062A\u0645\u064A\u0632\u0629\u060C \u0648\u0646\u0633\u062E\u0629/\u0646\u0637\u0627\u0642 \u0645\u0648\u062B\u0642\u0629.",
