    "v062.error.TAXONOMY_LIMIT": "\u0648\u064A\u062A\u062C\u0627\u0648\u0632 \u0627\u0644\u062C\u062F\u0648\u0644 \u0627\u0644\u0643\u0627\u0645\u0644 \u0644\u0644\u0645\u0631\u0627\u062C\u0639 \u0623\u0648 \u0627\u0644\u0645\u0631\u0627\u0642\u0628\u0629 \u0627\u0644\u0642\u0627\u0626\u0645\u0629 \u0639\u0644\u0649 \u0627\u0644\u062A\u062D\u0635\u064A\u0644 \u062D\u062F\u0627\u064B \u0644\u0644\u0627\u0633\u062A\u0639\u0631\u0627\u0636 \u0648\u0644\u0645 \u064A\u0637\u0628\u0642 \u0623\u064A \u062A\u062D\u0648\u0644 \u062C\u0632\u0626\u064A.",
    "v062.error.TAXONOMY_REVIEWER": "\u062A\u0633\u062C\u064A\u0644 \u0627\u0633\u0645 \u0627\u0644\u0645\u0633\u062A\u0639\u0631\u0636 \u0642\u0628\u0644 \u062A\u0637\u0628\u064A\u0642 \u062A\u0641\u0633\u064A\u0631 \u0627\u0644\u062A\u0635\u0646\u064A\u0641.",
    "v0618.action": "Review a projected coordinate couple",
    "v0618.safety": "(\u0628) \u0627\u062E\u062A\u064A\u0627\u0631 \u0627\u0644\u062D\u0642\u0644 \u0627\u0644\u0645\u0633\u062C\u0644 \u0641\u064A \u0627\u0644\u0634\u0631\u0642 \u0623\u0639\u0644\u0627\u0647 \u0648\u0634\u0631\u064A\u0643\u0647 \u0641\u064A \u0627\u0644\u0634\u0645\u0627\u0644 \u0623\u062F\u0646\u0627\u0647: \u0648\u0636\u0639 \u0646\u0638\u0627\u0645 \u0627\u0644\u0625\u0628\u0644\u0627\u063A \u0627\u0644\u0645\u0648\u062D\u062F \u0639\u0646 \u0627\u0644\u0645\u0635\u0627\u062F\u0631 \u0648\u0627\u0644\u0648\u062D\u062F\u0627\u062A \u0648\u0623\u0645\u0631 \u0627\u0644\u0645\u062D\u0648\u0631 \u0645\u0646 \u0627\u0644\u0623\u062F\u0644\u0629 \u0627\u0644\u0645\u062D\u062A\u0641\u0638 \u0628\u0647\u0627 \u0642\u0628\u0644 \u062A\u062D\u0648\u064A\u0644\u0647\u0627\u060C \u0648\u062A\u062D\u062A\u0641\u0638 \u062D\u0642\u0648\u0644 \u062E\u0637\u0648\u0637 \u0627\u0644\u0639\u0631\u0636 \u0627\u0644\u062C\u062F\u064A\u062F\u0629/\u0627\u0644\u0637\u0648\u0644 \u0628\u0627\u0644\u0632\u0648\u062C\u064A\u0646 \u0627\u0644\u0623\u0635\u0644\u064A\u064A\u0646\u060C \u0648\u062A\u0637\u0628\u0642 \u0627\u0644\u0646\u0638\u0645 \u063A\u064A\u0631 \u0627\u0644\u0645\u0639\u0631\u0648\u0641\u0629 \u0646\u062A\u0627\u0626\u062C \u0644\u0645 \u062A\u064F\u062D\u0644\u061B \u0648\u0644\u0627 \u064A\u064F\u062E\u0645\u0651\u064E\u0646 \u0623\u064A \u0646\u0638\u0627\u0645 \u0644\u0644\u0643\u0634\u0641 \u0639\u0646 \u0627\u0644\u0623\u0636\u0631\u0627\u0631 \u0623\u0648 \u0627\u0644\u0645\u062D\u0648\u0631 \u0623\u0648 \u0627\u0644\u0648\u062D\u062F\u0629.",
