    "v0618.eastNorthMetres": "\u0645\u0646\u0637\u0642\u0629 \u0645\u062E\u062A\u0627\u0631\u0629 \u0647\u064A \u0627\u0644\u0634\u0631\u0642\u061B \u0648\u0627\u0644\u0634\u0631\u064A\u0643 \u064A\u062A\u062C\u0647 \u0634\u0645\u0627\u0644\u0627\u061B \u0648\u0643\u0644\u0627\u0647\u0645\u0627 \u0645\u062A\u0631\u0627\u0646",
    "v0618.evidenceSafety": "EPSG:3857 conversion requires evidence-based review, a retained source locator and reviewer. Output is separate WGS 84 latitude/longitude in decimal degrees, this is an inverse projection, not a datum-grid or epoch transformation and not proof of measured accuracy.",
    "v0618.bounds": "\u0644\u0627 \u062A\u0646\u0641\u0630 \u0633\u0648\u0649 \u0627\u0644\u062C\u062F\u0627\u0648\u0644 \u0627\u0644\u0643\u0627\u0645\u0644\u0629 \u0627\u0644\u0645\u062D\u062F\u062F\u0629 \u0628\u0640 000 100 \u0635\u0641\u060C \u0648\u062A\u0646\u062A\u062C \u0627\u0644\u0623\u0632\u0648\u0627\u062C \u063A\u064A\u0631 \u0627\u0644\u0645\u062F\u0639\u0648\u0645\u0629 \u0623\u0648 \u0627\u0644\u0645\u0641\u0642\u0648\u062F\u0629 \u0623\u0648 \u0627\u0644\u0628\u0627\u0637\u0644\u0629 \u0623\u0648 \u063A\u064A\u0631 \u0627\u0644\u0645\u062A\u0648\u0641\u0631\u0629 \u0625\u062D\u062F\u0627\u062B\u064A\u0627\u062A \u0645\u0633\u062A\u0645\u062F\u0629 \u0628\u0634\u0643\u0644 \u0648\u0627\u0636\u062D \u0645\u0639 \u0646\u062A\u0627\u0626\u062C \u0648\u0627\u0636\u062D\u0629\u061B \u0648\u062A\u0638\u0644 \u0627\u0644\u0642\u064A\u0645 \u0627\u0644\u0645\u0635\u062F\u0631\u064A\u0629 \u0623\u062F\u0648\u064A\u0629\u060C \u0648\u064A\u0633\u062A\u062E\u062F\u0645 \u0639\u062F\u062F \u0643\u0628\u064A\u0631 \u0645\u0646 \u0627\u0644\u0646\u0648\u0627\u062A\u062C \u0645\u0627 \u064A\u0635\u0644 \u0625\u0644\u0649 15 \u0631\u0642\u0645\u0627\u064B \u0643\u0628\u064A\u0631\u0627\u064B \u062F\u0648\u0646 \u0623\u0646 \u064A\u0624\u0643\u062F \u0623\u0646 \u0627\u0644\u0642\u064A\u0627\u0633 \u0644\u0647 \u0647\u0630\u0627 \u0627\u0644\u062F\u0642\u0629.",
    "v0618.privacy": "\u0648\u0645\u0646 \u0634\u0623\u0646 \u062A\u0637\u0628\u064A\u0642 \u0647\u0630\u0627 \u0627\u0644\u0627\u0633\u062A\u0639\u0631\u0627\u0636 \u0623\u0646 \u064A\u0633\u062C\u0644 \u0643\u0644 \u0645\u0646 \u0627\u0644\u0645\u062F\u062E\u0644\u0627\u062A \u0627\u0644\u0645\u0646\u0633\u0651\u064E\u0642\u0629 \u0648\u0643\u0644\u0627 \u0627\u0644\u0645\u062C\u0627\u0644\u064A\u0646 \u0627\u0644\u0645\u0633\u062A\u0645\u062F\u064A\u0646 \u0645\u0646 \u0627\u0644\u062A\u0646\u0633\u064A\u0642 \u0639\u0644\u0649 \u0646\u062D\u0648 \u064A\u062A\u0633\u0645 \u0628\u0627\u0644\u062D\u0633\u0627\u0633\u064A\u0629 \u0641\u064A \u0627\u0644\u0628\u064A\u0627\u0646\u0627\u062A \u0627\u0644\u0641\u0648\u0642\u064A\u0629 \u0627\u0644\u0639\u0645\u0644\u064A\u0629 \u0627\u0644\u0645\u0631\u0627\u062C\u0639\u0629.() \u062B\u0645 \u062A\u064F\u0648\u0642\u0641 \u0627\u0644\u0635\u0627\u062F\u0631\u0627\u062A \u0627\u0644\u0639\u0627\u0645\u0629 \u0647\u0630\u0647 \u0627\u0644\u0645\u0648\u0627\u062F \u0628\u0645\u0648\u062C\u0628 \u0642\u0648\u0627\u0639\u062F \u0627\u0644\u062D\u0633\u0627\u0633\u064A\u0629 \u0627\u0644\u0642\u0627\u0626\u0645\u0629\u061B \u0648\u0644\u0627 \u062A\u0632\u0627\u0644 \u0627\u0644\u0623\u0635\u0648\u0644 \u0627\u0644\u062E\u0627\u0635\u0629 \u062F\u0642\u064A\u0642\u0629.",
    "v0618.issue.unknownCrs": "The source CRS remains unknown; no coordinate was inferred.",
    "v0618.issue.missingComponent": "\u0639\u0646\u0635\u0631 \u062A\u0646\u0633\u064A\u0642 \u0648\u0627\u062D\u062F \u0645\u0641\u0642\u0648\u062F",
    "v0618.issue.invalidNumeric": "\u0639\u0646\u0635\u0631 \u0627\u0644\u062A\u0646\u0633\u064A\u0642 \u0644\u064A\u0633 \u0631\u0642\u0645\u0627\u064B \u0639\u0634\u0631\u064A\u0627\u064B \u0645\u062D\u062F\u0648\u062F\u0627\u064B",
    "v0618.issue.outsideExtent": "\u0648\u064A\u0642\u0639 \u0647\u0630\u0627\u0646 \u0627\u0644\u0632\u0648\u062C\u0627\u0646 \u062E\u0627\u0631\u062C \u0646\u0637\u0627\u0642 \u062E\u0631\u064A\u0637\u0629 \u0627\u0644\u0648\u064A\u0628 \u0627\u0644\u0645\u0631\u0628\u0639 \u0627\u0644\u0645\u0646\u0641\u0630\u0629.",
