    "v062.error.COORDINATE_CRS": "(\u0628) \u0627\u062E\u062A\u064A\u0627\u0631 \u0646\u0638\u0627\u0645 \u0645\u0635\u062F\u0631 \u0645\u062F\u0639\u0648\u0645 \u0635\u0631\u0627\u062D\u0629 \u0623\u0648 \u063A\u064A\u0631 \u0645\u0639\u0631\u0648\u0641\u061B \u0648\u064A\u062C\u0628 \u0623\u0646 \u064A\u0636\u0627\u0647\u064A \u0627\u0644\u0646\u0638\u0627\u0645 \u0627\u0644\u0645\u0646\u0633\u0642 \u0644\u0644\u0633\u064A\u0627\u0633\u0627\u062A \u0648\u0627\u0644\u0647\u062F\u0641 \u0627\u0644\u0625\u0633\u0642\u0627\u0637 \u0627\u0644\u0639\u0643\u0633\u064A \u0627\u0644\u0645\u0646\u0641\u0630.",
    "v062.error.COORDINATE_REVIEWER": "\u062A\u0633\u062C\u064A\u0644 \u0627\u0633\u0645 \u0627\u0644\u0645\u0633\u062A\u0639\u0631\u0636 \u0644\u062A\u0641\u0633\u064A\u0631 \u0634\u0627\u0645\u0644.",
    "v062.error.COORDINATE_EVIDENCE": "\u0648\u064A\u0642\u062A\u0636\u064A \u0627\u0644\u062A\u062D\u0648\u064A\u0644 \u0627\u0644\u0645\u062A\u0648\u0642\u0651\u0639 \u0627\u0644\u0645\u0639\u0631\u0648\u0641 \u0627\u0644\u0627\u062D\u062A\u0641\u0627\u0638 \u0628\u0623\u062F\u0644\u0629 \u0635\u0627\u062F\u0631\u0629 \u0639\u0646 \u062F\u0627\u0626\u0631\u0629 \u0627\u0644\u0627\u0633\u062A\u062E\u0628\u0627\u0631\u0627\u062A \u0627\u0644\u0645\u0631\u0643\u0632\u064A\u0629 \u0645\u0639 \u062C\u0647\u0627\u0632 \u062A\u062D\u062F\u064A\u062F \u0627\u0644\u0645\u0648\u0627\u0642\u0639\u060C \u0648\u0627\u0633\u062A\u0639\u0631\u0627\u0636 \u0645\u0633\u062A\u0646\u062F \u0625\u0644\u0649 \u0627\u0644\u0623\u062F\u0644\u0629\u060C \u0648\u0641\u0624\u0631 \u0634\u0631\u0642\u064A\u0629/\u0634\u0645\u0627\u0644\u064A\u0629 \u0648\u0627\u0636\u062D\u0629.",
    "v062.error.COORDINATE_LIMIT": "\u0648\u064A\u062A\u062C\u0627\u0648\u0632 \u062C\u062F\u0648\u0644 \u0627\u0644\u062A\u0646\u0633\u064A\u0642 \u0627\u0644\u0643\u0627\u0645\u0644 000 100 \u0635\u0641\u061B \u0648\u0644\u0627 \u064A\u0637\u0628\u0642 \u0623\u064A \u062A\u062D\u0648\u064A\u0644 \u062C\u0632\u0626\u064A.",
    "v0618.unresolvedPolicy": "\u0648\u062A\u062A\u0631\u0643 \u0627\u0644\u0623\u0632\u0648\u0627\u062C \u063A\u064A\u0631 \u0627\u0644\u0645\u0639\u0632\u0648\u0644\u0629 \u0648\u0627\u0644\u0645\u062A\u0636\u0627\u0631\u0628\u0629 \u0643\u0644\u0627\u064B \u0645\u0646 \u062E\u0637 \u0627\u0644\u0639\u0631\u0636 \u0627\u0644\u0645\u0634\u062A\u0642 \u0648\u062E\u0637 \u0627\u0644\u0637\u0648\u0644 \u0641\u0627\u0631\u063A\u0627\u064B\u060C \u0645\u0639 \u0648\u062C\u0648\u062F \u062D\u0642\u0644 \u0645\u0633\u062A\u0642\u0644 \u0645\u0646 \u062F\u0648\u0644 \u0627\u0644\u0627\u0633\u062A\u0639\u0631\u0627\u0636\u060C \u0648\u0644\u0627 \u062A\u0632\u0627\u0644 \u0627\u0644\u0642\u064A\u0645 \u0627\u0644\u0645\u0633\u062C\u0644\u0629 \u0644\u0644\u0645\u062F\u062E\u0644\u0627\u062A \u0633\u0644\u064A\u0645\u0629\u060C \u0648\u0644\u0627 \u062A\u0632\u0627\u0644 \u0627\u0644\u0645\u064A\u0627\u062F\u064A\u0646 \u0627\u0644\u0645\u0634\u062A\u0642\u0629 \u062A\u064F\u0633\u062A\u0646\u062A\u062C \u0639\u0646\u062F\u0645\u0627 \u064A\u0643\u0648\u0646 \u0623\u064A \u0632\u0648\u062C \u063A\u064A\u0631 \u0641\u0627\u0631\u063A \u062F\u0648\u0646 \u062D\u0644\u060C \u0623\u0648 \u063A\u064A\u0631 \u0645\u0639\u0631\u0648\u0641 \u0639\u0646\u062F\u0645\u0627 \u064A\u0643\u0648\u0646 \u0627\u0644\u0645\u0635\u062F\u0631 \u063A\u064A\u0631 \u0645\u0639\u0631\u0648\u0641.",
