    "v06.exportNotes": "\u4E0B\u8F7D\u672C\u5730\u5DE5\u4F5C\u8BF4\u660E",
    "v06.why.name": "\u5B57\u6BB5\u540D\u79F0\u7C7B\u4F3C\u4E8E\u4E00\u4E2A\u5E38\u89C1\u7684\u7814\u7A76\u672F\u8BED\u3002\u8FD9\u4E2A\u57FA\u4E8E\u540D\u79F0\u7684\u89C4\u5219\u4E0D\u80FD\u786E\u7ACB\u79D1\u5B66\u610F\u4E49,\u5373\u4F7F\u503C\u770B\u8D77\u6765\u662F\u5408\u7406\u7684\u3002",
    "v06.why.unknown": "\u6CA1\u6709\u627E\u5230\u53EF\u8FA9\u9A73\u7684\u5B57\u6BB5\u610F\u4E49\u3002 \u5E78\u5B58\u6587\u6863\u53EF\u80FD\u6709\u6240\u5E2E\u52A9\u3002 \u7559\u4E0B\u8FD9\u4E2A\u672A\u77E5\u5B57\u6BB5\u6BD4\u731C\u6D4B\u5B89\u5168 \u3002",
    "v06.why.conflict": "\u8BB0\u5F55\u7684\u89E3\u91CA\u76F8\u4E92\u77DB\u76FE,\u4F7F\u76F8\u4E92\u7ADE\u4E89\u7684\u8BC1\u636E\u6E05\u6670\u53EF\u89C1,\u800C\u4E0D\u662F\u81EA\u52A8\u9009\u62E9\u3002",
    "v06.why.mapping": "\u5DF2\u786E\u8BA4\u7684\u5B57\u6BB5\u5B9A\u4E49\u6CA1\u6709\u8BB0\u5F55\u6807\u51C6\u6620\u5C04 \u3002 \u540D\u79F0\u663E\u793A\u6B64\u5019\u9009\u4EBA; \u8BF7\u5148\u68C0\u67E5\u5B9E\u9645\u542B\u4E49\u548C\u8868\u683C\u7ED3\u6784 \u3002",
    "v06.why.trim": "\u4E00\u4E9B\u62BD\u6837\u7684\u6570\u503C\u5305\u542B\u5468\u56F4\u7684\u767D\u7A7A\u95F4,\u5728\u5E94\u7528\u6B64\u673A\u68B0\u4FEE\u590D\u524D\u9700\u8981\u5B8C\u6574\u7684\u8868\u683C\u9884\u89C8.",
    "v06.why.missing": "\u8FD9\u4E9B\u5B57\u9762\u7B26\u53F7\u7C7B\u4F3C\u4E8E\u7F3A\u5C11\u4EF7\u503C\u7684\u5E38\u89C4,\u4E5F\u53EF\u80FD\u662F\u771F\u6B63\u7684\u6D4B\u91CF\u6216\u4EE3\u7801\u3002\u6CA1\u6709\u8BC1\u636E,\u4E0D\u8981\u8F6C\u6362\u3002",
    "v06.why.date": "\u91C7\u6837\u65E5\u671F\u65E2\u5141\u8BB8\u9996\u65E5\u8BFB\u6570,\u4E5F\u5141\u8BB8\u9996\u6708\u8BFB\u6570\u3002\u4E24\u4F4D\u6570\u7684\u5E74\u4EFD\u4E5F\u9700\u8981\u4E16\u7EAA\u7684\u8BC1\u636E\u3002\u5DE5\u4F5C\u533A\u4E0D\u4F1A\u81EA\u52A8\u9009\u62E9\u3002",
    "v06.why.unit": "\u5217\u540D\u540E\u7F00\u7C7B\u4F3C\u5355\u4F4D,\u662F\u540D\u5B57\u7684\u63A8\u8BBA,\u4E0D\u662F\u786E\u8BA4\u7684\u6D4B\u91CF\u4E0A\u4E0B\u6587.",
    "v06.why.coordinate": "\u5B57\u6BB5\u540D\u79F0\u7C7B\u4F3C\u5750\u6807\u8F74\u3002\u9664\u975E\u6709\u6587\u4EF6\u8BB0\u5F55,\u5426\u5219\u57FA\u51C6\u548C\u5750\u6807\u53C2\u8003\u7CFB\u7EDF\u4ECD\u7136\u672A\u77E5 \u3002",
    "v06.why.taxonomy": "\u6B64\u5B57\u6BB5\u53EF\u80FD\u8BB0\u5F55\u4E00\u4E2A\u5206\u7C7B\u540D\u79F0\u6216\u4EE3\u7801\u3002 \u5386\u53F2\u540D\u79F0\u4ECD\u4E3A\u6587\u5B57\u540D\u79F0; \u5F53\u524D\u540D\u79F0\u7684\u67E5\u627E\u9700\u8981\u660E\u786E\u7684\u5BA1\u67E5\u548C\u6765\u6E90 \u3002",
    "v06.why.relationship": "\u4E24\u4E2A\u5B57\u6BB5\u5BF9\u9F50\u4E86\u6B63\u6001\u540D\u79F0\u548C\u91CD\u53E0\u7684\u6837\u672C\u503C\u3002\u5BA1\u67E5\u6BCD\u4F53\u72EC\u6709\u6027\u3001\u57FA\u672C\u6027\u3001\u672A\u5339\u914D\u7684\u5F15\u7528\u548C\u771F\u6B63\u7684\u79D1\u5B66\u8054\u7CFB\u3002",
    "v06.why.codebook": "\u8868\u683C\u540D\u79F0\u7C7B\u4F3C\u4E8E\u4EE3\u7801\u7C3F\u3002 \u5B83\u7684\u524D\u4E24\u4E2A\u5B57\u6BB5\u663E\u793A\u4E3A\u5019\u9009\u4EE3\u7801\u548C\u542B\u4E49; \u8FD9\u4E0D\u662F\u4E00\u4E2A\u786E\u8BA4\u7684\u8BCD\u5178\u3002 \u51B2\u7A81\u7684\u5B9A\u4E49\u4ECD\u7136\u53EF\u89C1 \u3002",
    "v06.why.metadata": "\u9879\u76EE\u80CC\u666F\u7F3A\u5931\u6216\u672A\u7ECF\u8BC1\u5B9E\u3002 \u8BF7\u53EA\u63CF\u8FF0\u5E78\u5B58\u7684\u8BC1\u636E\u53EF\u4EE5\u8BC1\u660E\u4EC0\u4E48 \u3002",
