    "v064.error.LARGE_SOURCE_INTEGRITY": "\u4FDD\u7559\u6E90\u4E0E\u5176\u8BB0\u5F55\u7684\u6563\u5217\u6216\u957F\u5EA6\u4E0D\u540C\u3002 \u8F6F\u4EF6\u5305\u5BFC\u51FA\u88AB\u5C4F\u853D; \u4FDD\u7559\u6E90\u5E76\u56DE\u6536\u7ECF\u6838\u5B9E\u7684\u72EC\u7ACB\u526F\u672C \u3002",
    "v064.error.LARGE_METADATA_DRAFT_STORAGE": "\u6D4F\u89C8\u5668\u8349\u7A3F\u5B58\u50A8\u4E0D\u53EF\u7528\u3002 \u60A8\u7684\u6587\u672C\u4ECD\u7136\u4FDD\u5B58\u5728\u672C\u6807\u7B7E\u7684\u5185\u5B58\u4E2D, \u4F46\u53EF\u80FD\u65E0\u6CD5\u5E78\u5B58 \u3002",
