    "v064.bulkUndo": "\u8FD9\u4E00\u884C\u52A8\u6062\u590D\u4E86\u7ECF\u5BA1\u67E5\u7684\u6574\u4E2A\u6279\u6B21 {count} \u5355\u5143\u683C\u3002\u663E\u793A\u7684\u5355\u503C\u662F\u7B2C\u4E00\u4E2A\u53D7\u5F71\u54CD\u7684\u5355\u5143\u683C;\u6BCF\u4E2A\u53D7\u5F71\u54CD\u7684\u5355\u5143\u683C\u5728\u4EA4\u6613\u5F00\u59CB\u524D\u90FD\u7ECF\u8FC7\u6838\u67E5\u3002",
