    "v064.error.LARGE_BATCH_OPERATION": "\u8FD9\u6279\u53EA\u652F\u6301\u8FB9\u7F18- \u767D\u7A7A\u53BB\u9664\u3002 \u79D1\u5B66\u89E3\u91CA\u9700\u8981\u5355\u4E2A\u8BC1\u636E\u548C\u5BA1\u67E5 \u3002",
    "v064.error.LARGE_BATCH_REASON": "\u589E\u52A0\u5BA1\u67E5\u6279\u6B21\u7406\u7531,\u5C06\u7406\u7531\u4FDD\u7559\u57282000\u4E2A\u5B57\u7B26\u4E4B\u5185,\u5BA1\u67E5\u8EAB\u4EFD\u4FDD\u7559\u5728200\u4E2A\u5B57\u7B26\u4E4B\u5185.",
