    "v064.error.LARGE_BATCH_STALE": "\u5DE5\u4F5C\u6570\u636E\u5728\u9884\u89C8\u540E\u6709\u6240\u53D8\u5316\u3002 \u6CA1\u6709\u6267\u884C \u3002 \u518D\u6B21\u9884\u89C8\u5F53\u524D\u6570\u636E \u3002",
