    "v064.error.LARGE_BATCH_HISTORY": "\u6279\u91CF\u503C\u4E0E\u5176\u8BB0\u5F55\u7684\u5386\u53F2\u4E0D\u540C\u3002 \u64A4\u6D88\u6216\u91CD\u505A\u88AB\u5C4F\u853D, \u6574\u4E2A\u4EA4\u6613\u88AB\u5377\u56DE \u3002",
    "v065.linkTitle": "\u5927\u578B\u6570\u636E\u96C6\u7684\u8FDE\u63A5",
