    "v065.linkPackageSafety": "\u79C1\u4EBA\u8F6F\u4EF6\u5305\u65E2\u5305\u62EC\u539F\u59CB\u6765\u6E90,\u4E5F\u5305\u62EC\u6587\u5B57\u5DE5\u4F5C\u8868\u3001\u72EC\u7ACB\u7684\u5143\u6570\u636E\u548C\u5386\u53F2\u3001\u7ECF\u5BA1\u67E5\u7684\u7ED3\u5408\u98DF\u8C31\u548C\u884D\u751F\u7684 CSV \u3002\u7F3A\u5C11\u3001\u65E0\u6CD5\u5339\u914D\u548C\u76F8\u4E92\u51B2\u7A81\u7684\u5BC6\u94A5\u6709\u660E\u786E\u7684\u7ED3\u679C\u548C\u7A7A\u7684\u7236\u5355\u5143\u683C\u3002\u6CA1\u6709\u79D1\u5B66\u5173\u7CFB\u6216\u6807\u51C6\u7B26\u5408\u6027\u81EA\u52A8\u5F97\u5230\u786E\u8BA4\u3002 CSV \u9650\u5236:512 MiB\u3002",
    "v065.pairedRevisions": "\u513F\u5DE5\u4FEE\u8BA2 {child} \u5BB6\u957F\u5DE5\u4F5C\u4FEE\u8BA2 {parent}",
