    "v065.linkSaved": "\u5DF2\u58F0\u660E\u5173\u7CFB\u4E0E\u5BA1\u67E5\u5386\u53F2\u4E00\u8D77\u4FDD\u5B58\u3002 \u6570\u636E\u548C\u539F\u59CB\u5B57\u8282\u4E0D\u53D8; \u5B8C\u6574\u6027\u8BA1\u6570\u4E0E\u79D1\u5B66\u610F\u4E49\u5206\u79BB \u3002",
    "v065.downloadReady": "\u4E3A\u4E00\u6B21\u6027\u4E0B\u8F7D\u51C6\u5907\u7684\u9A8C\u8BC1\u5173\u7CFB\u5305\u3002\u5176\u4E2D\u65E2\u5305\u62EC\u539F\u4EF6,\u4E5F\u5305\u62EC\u6240\u6709\u7684\u513F\u7AE5\u8BB0\u5F55;\u6B64\u5BFC\u51FA\u5305\u542B\u79C1\u4EBA\u6570\u636E\u3002",
    "v065.savedRevisions": "\u6700\u540E\u8BB0\u5F55\u7684\u68C0\u67E5:\u513F\u7AE5\u5BA1\u6821 {child},\u7236\u4FEE\u8BA2 {parent}\u3002\u5728\u4F7F\u7528\u5F53\u524D\u6570\u636E\u4E4B\u524D\u91CD\u65B0\u68C0\u67E5\u3002",
    "v065.recheckLink": "\u6253\u5F00\u58F0\u660E\u548C\u91CD\u65B0\u68C0\u67E5",
    "v065.noSavedLinks": "\u5C1A\u672A\u4E3A\u8FD9\u9879\u8C03\u67E5\u7533\u62A5\u4EFB\u4F55\u5173\u7CFB\u3002",
    "v065.error.LARGE_LINK_NOT_READY": "\u5728\u68C0\u67E5\u53CC\u65B9\u7684\u5173\u7CFB\u4E4B\u524D,\u5FC5\u987B\u5F7B\u5E95\u5206\u6790\u8FD9\u4E24\u9879\u8C03\u67E5\u3002",
    "v065.error.LARGE_LINK_COLUMNS": "\u6BCF\u8FB9\u9009\u62E9\u4E00\u4E2A\u81F3\u4E94\u4E2A\u4E0D\u540C\u7684\u5BC6\u94A5\u5B57\u6BB5,\u660E\u786E\u5BF9\u6570\u76F8\u540C.",
    "v065.error.LARGE_LINK_REASON": "\u589E\u52A0\u89E3\u91CA\u58F0\u660E\u5173\u7CFB\u7684\u7406\u7531.",
    "v065.error.LARGE_LINK_REVIEW": "\u5728\u786E\u8BA4\u58F0\u660E\u4E4B\u524D\u9009\u62E9\u542B\u4E49\u72B6\u6001\u5E76\u6DFB\u52A0\u60A8\u7684\u590D\u8BAE\u8EAB\u4EFD\u3002 \u8F6F\u4EF6\u5305\u7684\u7F16\u5199\u9700\u8981\u590D\u8BAE\u8EAB\u4EFD\u548C\u7406\u7531 \u3002",
    "v065.error.LARGE_LINK_STALE": "\u68C0\u67E5\u540E, \u6570\u636E\u96C6\u3001 \u5143\u6570\u636E\u6216\u5DE5\u4F5C\u8868\u6307\u7EB9\u53D1\u751F\u4E86\u53D8\u5316\u3002 \u6CA1\u6709\u6267\u884C\u6216\u5BFC\u51FA\u4EFB\u4F55\u4EFB\u52A1\u3002 \u8BF7\u518D\u6B21\u68C0\u67E5\u5F53\u524D\u5BC6\u94A5 \u3002",
    "v065.error.LARGE_LINK_INVALID": "\u8FD9\u4E00\u5173\u7CFB\u58F0\u660E\u5728\u6B64\u6B21\u8C03\u67E5\u4E2D\u5DF2\u4E0D\u5B58\u5728.",
    "v065.error.LARGE_LINK_LIMIT": "\u6B64\u5143\u6570\u636E\u6587\u6863\u8D85\u8FC7\u5176\u4FDD\u5B58\u9650\u5236, \u6216\u8005\u5DF2\u7ECF\u8BB0\u5F55\u4E86 100 \u4E2A\u5173\u7CFB\u3002 \u6CA1\u6709\u66F4\u6539 \u3002",
    "v065.error.LARGE_LINK_EXPORT_LIMIT": "\u6240\u5173\u8054\u7684 CSV \u8D85\u8FC7 512 MiB \u3002\u5BFC\u51FA\u72EC\u7ACB\u8868\u683C\u6216\u4F7F\u7528\u8F83\u5C0F\u7684\u8C03\u67E5\u3002\u6CA1\u6709\u6539\u53D8\u3002",
    "v065.error.LARGE_LINK_DOWNLOAD_BUSY": "\u6B63\u5728\u51C6\u5907\u6216\u6B63\u5728\u5EFA\u9020\u8FC7\u591A\u7684\u4E34\u65F6\u8F6F\u4EF6\u5305\u3002 \u5B8C\u6210\u4E00\u4E2A\u51C6\u5907\u7684\u4E0B\u8F7D\u5E76\u518D\u6B21\u5C1D\u8BD5; \u4E34\u65F6\u4E0B\u8F7D\u8BBF\u95EE\u5728\u4E94\u5206\u949F\u540E\u5230\u671F \u3002",
    "v065.error.LARGE_LINK_DOWNLOAD_EXPIRED": "\u6B64\u4E00\u6B21\u6027\u4E0B\u8F7D\u5DF2\u88AB\u8017\u5C3D\u6216\u8FC7\u671F \u3002 \u4ECE\u65B0\u5BC6\u94A5\u68C0\u67E5\u4E2D\u518D\u6B21\u51C6\u5907\u8F6F\u4EF6\u5305 \u3002",
    "v065.error.LARGE_LINK_WORKING_SHAPE": "\u5DE5\u4F5C\u8BB0\u5F55\u4E0D\u518D\u5177\u6709\u5BFC\u5165\u7684\u5B57\u9762\u5F62\u72B6\u6216\u6E90\u8BB0\u5F55\u8EAB\u4EFD\u3002 \u64CD\u4F5C\u88AB\u5C4F\u853D; \u6CA1\u6709\u663E\u793A\u3001 \u6DFB\u52A0\u6216\u4E22\u5F03\u503C \u3002",
    "v065.linkDraftSafety": "\u8349\u7A3F\u5BC6\u94A5\u914D\u5BF9\u548C\u5BA1\u67E5\u6587\u672C\u4FDD\u7559\u5728\u6B64\u6D4F\u89C8\u5668\u6807\u7B7E\u4E2D, \u5305\u62EC\u91CD\u65B0\u88C5\u5165\u540E\u3002 \u5173\u95ED\u6807\u7B7E\u53EF\u4EE5\u5220\u9664\u5B83\u4EEC\u3002 \u5143\u6570\u636E\u53EA\u6709\u5728\u4FDD\u5B58\u58F0\u660E\u65F6\u624D\u4F1A\u66F4\u6539; \u5DF2\u5BA1\u67E5\u7684\u4E0B\u8F7D\u8BB0\u5F55\u81EA\u5DF1\u7684\u98DF\u8C31\u800C\u4E0D\u6539\u53D8\u8C03\u67E5 \u3002",
    "v065.controlSafety": "\u6B64\u8C03\u67E5\u53EA\u5728\u6B64\u7A97\u53E3\u4E2D\u8BFB\u53D6\u3002 \u83B7\u53D6\u7F16\u8F91\u63A7\u5236\u4F1A\u8BA9\u53E6\u4E00\u4E2A\u7A97\u53E3\u53EA\u8BFB\u5E76\u4FDD\u7559\u5176\u672A\u627F\u8BFA\u6587\u672C\u3002 \u539F\u59CB\u6570\u636E\u548C\u5DF2\u627F\u8BFA\u7684\u5386\u53F2\u4FDD\u6301\u4E0D\u53D8 \u3002",
    "v066.restoreTitle": "\u4ECE\u4E00\u4E2A\u4FDD\u5B58\u5305\u4E2D\u6062\u590D\u4E00\u4E2A\u5927\u8C03\u67E5",
    "v066.restoreSafety": "\u5728\u6062\u590D\u5355\u72EC\u8C03\u67E5\u524D, \u9A8C\u8BC1\u539F\u59CB\u7F16\u8F91\u548C\u91CD\u64AD\u6240\u6709\u8BB0\u5F55\u7684\u7F16\u8F91\u3002 \u73B0\u6709\u8C03\u67E5\u88AB\u4FDD\u5B58\u3002 \u6821\u9A8C\u548C\u4E0D\u662F\u79D1\u5B66\u771F\u7406\u7684\u8BC1\u636E \u3002",
    "v066.choosePackage": "\u5728\u6B64\u4E22\u5F03\u4FDD\u5B58\u7684 ZIP \u6216\u5355\u51FB\u9009\u62E9",
    "v066.restoreLimits": "\u538B\u7F29\u6700\u591A512\u4E2A\u7C73B,\u6269\u59271\u4E2A\u5409B\u3002 CSV \u9650\u5236\u4ECD\u7136\u9002\u7528\u3002\u4E0A\u4F20\u548C\u5DF2\u6838\u5B9E\u7684\u9884\u89C8\u572815\u5206\u949F\u540E\u8FC7\u671F;\u53D6\u6D88\u4E34\u65F6\u6062\u590D\u6587\u4EF6\u3002",
