    "v066.restored": "\u9A8C\u8BC1\u7684\u5305\u88F9\u4F5C\u4E3A\u5355\u72EC\u7684\u8C03\u67E5\u6062\u590D.",
    "v066.verificationFailed": "\u8F6F\u4EF6\u5305\u9A8C\u8BC1\u5931\u8D25\u3002 \u6CA1\u6709\u6062\u590D\u8C03\u67E5 \u3002 {detail}",
