    "v066.error.LARGE_RESTORE_REVIEW": "\u5728\u6062\u590D\u524D\u8F93\u5165\u5BA1\u67E5\u8EAB\u4EFD\u548C\u7406\u7531\u3002",
    "v066.error.LARGE_RESTORE_EXISTS": "\u76EE\u6807\u8C03\u67E5\u5DF2\u7ECF\u5B58\u5728\u3002 \u6CA1\u6709\u8986\u76D6\u73B0\u6709\u6587\u4EF6 \u3002",
    "v066.error.LARGE_RESTORE_SOURCE": "\u4FDD\u5B58\u4E0B\u6765\u7684\u539F\u4EF6\u4E0D\u590D\u5236\u8BB0\u5F55\u7684\u8868\u683C\u5F62\u72B6.",
    "v066.error.LARGE_RESTORE_METADATA": "\u5143\u6570\u636E\u5B9A\u4E49\u6216\u5386\u53F2\u4E0D\u4F1A\u5F62\u6210\u6709\u6548\u7684\u8BB0\u5F55\u94FE.",
    "v066.error.LARGE_RESTORE_HISTORY": "\u5DF2\u5F55\u5236\u7684\u7F16\u8F91\u4E0D\u5F62\u6210\u6709\u6548\u7684\u53EF\u91CD\u64AD\u5386\u53F2 \u3002",
    "v066.error.LARGE_RESTORE_REPLAY": "\u91CD\u64AD\u539F\u4F5C\u4E0D\u590D\u5236\u5305\u88C5\u7684\u5DE5\u4F5C\u8868.",
