    "v067.readPreview": "\u8BFB\u53D6\u7684\u6587\u4EF6\u8BC1\u636E",
    "v067.evidenceSafety": "\u4FDD\u5B58\u6765\u6E90\u7684\u8FB9\u754C\u6458\u5F55, \u5B83\u4EEC\u662F\u652F\u6301\u6027\u8BC1\u636E, \u4E0D\u662F\u786E\u8BA4\u7684\u5143\u6570\u636E\u6216\u5B8C\u6574\u7684\u91CD\u5EFA\u6587\u6863\u3002 \u8BF7\u5728\u89E3\u91CA\u6216\u5F15\u7528\u542B\u4E49\u524D\u68C0\u67E5\u539F\u4EF6 \u3002",
