    "v067.noPath": "\u4E0D\u8F6C\u6362\u8868\u683C\u800C\u4FDD\u7559\u7ED3\u6784",
    "v067.recordCount": "{count} \u8981\u7D20",
    "v067.pathSafety": "\u9009\u62E9\u7CBE\u786E\u7684\u6269\u5C55\u540D\u8DEF\u5F84, \u7136\u540E\u5728\u5BFC\u5165\u524D\u518D\u6B21\u68C0\u67E5 \u3002 \u53EA\u6709\u5E73\u9762\u5C5E\u6027\u548C\u7EAF\u5B50\u6587\u672C\u53EF\u4EE5\u7EC4\u6210\u8868\u683C \u3002 \u91CD\u590D\u3001 \u5D4C\u5165\u6216\u6DF7\u5408\u7684\u5185\u5BB9\u4F1A\u88AB\u4FDD\u7559\u800C\u4E0D\u9759\u9ED8\u7684\u5E73\u9762 \u3002 \u7F3A\u5931\u548C\u7A7A\u5143\u7D20\u5728\u5DE5\u4F5C\u65F6\u5171\u4EAB\u7A7A\u767D CSV;\u539F\u6587\u4FDD\u7559\u5176\u533A\u522B.",
    "v068.pageLocation": "PDF \u9875\u9762 {index}",
    "v068.noRecoveredText": "\u6B64\u9875\u9762\u4E2D\u627E\u4E0D\u5230\u6587\u672C \u3002 \u5B83\u53EF\u80FD\u662F\u7A7A\u767D\u7684, \u4EC5\u662F\u56FE\u50CF, \u6216\u8005\u9700\u8981\u4E0D\u540C\u7684\u8BFB\u53D6/ OCR \u5DE5\u4F5C\u6D41\u7A0B \u3002 \u8FD9\u5E76\u4E0D\u80FD\u786E\u8BA4\u7F3A\u5C11\u4FE1\u606F \u3002",
    "v068.pdfBounds": "\u6587\u672C\u5C42\u8282\u5F55\u53EA\u5305\u542B:\u524D50\u9875,\u6BCF\u9875\u6700\u591A15\u4E07\u4E2A\u5B57\u7B26,\u6BCF\u98754000\u4E2A\u5B57\u7B26. \u9605\u8BFB\u987A\u5E8F,\u95F4\u8DDD,glyphs\u548C\u65E9\u671F\u7684OCR\u6587\u672C\u53EF\u80FD\u4E0D\u51C6\u786E. \u6CA1\u6709OCR,\u91CD\u5EFA\u7684\u8868\u683C\u5E03\u5C40,\u5BC6\u7801\u5904\u7406\u6216\u81EA\u52A8\u5143\u6570\u636E\u786E\u8BA4. \u5BA1\u67E5\u539F\u4EF6.",
