    "v0615.namedSafety": "\u547D\u540D\u6708\u683C\u5F0F\u4F7F\u7528\u82F1\u6587\u6708\u540D\u6216\u4E09\u5B57\u6BCD\u7F29\u5199\u548C\u56DB\u4F4D\u6570\u5E74\u4EFD\u3002\u6E90\u503C\u4E0D\u7FFB\u8BD1\u4E3A\u5176\u4ED6\u8BED\u8A00\u3002\u4E0D\u53EF\u80FD\u7684\u65E5\u671F\u4E3A\u5B57\u9762\u548C\u672A\u89E3\u51B3\u7684\u65E5\u671F\u3002",
    "v0615.hypotheses": "\u53EF\u80FD\u7684\u65E5/\u6708\u89E3\u91CA",
