    "v0615.centuryUnknown": "\u4E16\u7EAA\u662F\u672A\u7ECF\u8BC1\u5B9E\u7684",
    "v0615.error.DATE_POLICY": "\u9009\u62E9\u4E00\u4E2A\u7ECF\u8FC7\u5BA1\u67E5\u7684\u65E5\u671F\u653F\u7B56\u548C\u4E00\u4E2A100\u500D\u7684\u4E16\u7EAA\u3002",
    "v062.error.DATE_POLICY": "\u9009\u62E9\u4E00\u4E2A\u7ECF\u8FC7\u5BA1\u67E5\u7684\u65E5\u671F\u653F\u7B56\u548C\u4E00\u4E2A100\u500D\u7684\u4E16\u7EAA\u3002",
    "v0616.title": "\u5DF2\u6062\u590D\u7684\u9057\u7559\u6587\u5B57",
    "v0616.safety": "\u53EA\u8BFB\u4E3B\u5C42\u6587\u5B57\u8BC1\u636E\u3002 \u6B64\u9884\u89C8\u4E0D\u4F1A\u91CD\u6784\u6587\u6863\u3001 \u89E3\u51B3\u4FEE\u6539\u6216\u786E\u8BA4\u79D1\u5B66\u542B\u4E49\u3002 \u5B57\u6BB5\u548C\u9690\u85CF\u6216\u5220\u9664\u7684\u6587\u672C\u53EF\u80FD\u4E00\u8D77\u51FA\u73B0; \u5728\u4F9D\u8D56\u8282\u9009\u4E4B\u524D\u5BA1\u67E5\u539F\u4EF6 \u3002",
    "v0616.controls": "\u5B57\u7B26\u4F4D\u7F6E(CP)\u662F\u4E3B\u6545\u4E8B\u4E2D\u7684\u96F6\u57FA\u7684UTF-16\u5355\u5143. \u8DDD\u79BB\u7ED3\u675F\u4E8E\u5176\u6700\u540E\u4E00\u4E2A\u5355\u5143\u4E4B\u540E\u3002 \u63A7\u5236\u548C\u65B9\u5411\u683C\u5F0F\u5316\u5B57\u7B26\u4F5C\u4E3AQQU+XXXX\u27E7\u6807\u8BB0\u51FA\u73B0; \u6807\u7B7E\u548C\u6362\u884C\u7B26\u4F5C\u4E3A\u95F4\u9694\u4ECD\u7136\u53EF\u89C1 \u3002",
