    "v0616.unsupported": "\u683C\u5F0F\u5316\u3001\u8868\u683C\u3001\u9875\u9762\u5E03\u5C40\u3001\u5B57\u6BB5\u3001\u6CE8\u91CA\u3001\u811A\u6CE8\u3001\u9875\u7709\u3001\u6587\u672C\u6846\u3001\u4FEE\u8BA2\u7248\u5C5E\u6027\u548C\u5D4C\u5165\u5F0F\u5BF9\u8C61\u4E0D\u91CD\u5EFA\u3002Macros\u548C\u5916\u90E8\u5185\u5BB9\u4ECE\u672A\u6267\u884C\u6216\u83B7\u53D6\u3002\u6280\u672F\u8BC1\u636E\u4E2D\u4FDD\u7559\u4E86\u5176\u4ED6\u6545\u4E8B\u8BA1\u6570\u548C\u5757\u4F4D\u7F6E\u3002",
    "v0616.bounds": "\u9884\u89C8\u9650\u5236:200\u4E2A\u6587\u672C\u5757,\u517115\u4E07\u4E2A\u5B57\u7B26,\u6BCF\u57574000\u4E2A\u5B57\u7B26. \u56DE\u6536\u62D2\u7EDD\u8F93\u5165\u8D85\u8FC7\u5176\u5B8C\u6574\u7684\u7ED3\u6784\u9650\u5236:1,000,000\u4E2A\u4E3B\u6545\u4E8B\u5355\u5143,2,000,000\u4E2A\u6545\u4E8B\u5355\u5143\u548C10,000\u4E2A\u4F5C\u54C1. \u5DE5\u4EBA\u62E5\u6709256\u4E2A\u7C73B\u5185\u5B58\u9650\u5236\u548C20\u79D2\u7684\u6700\u540E\u671F\u9650.",
    "v0616.sourceSafety": "\u51C6\u786E\u7684\u539F\u59CB\u6587\u4EF6\u4F5C\u4E3A\u4F50\u8BC1\u8BC1\u636E\u4FDD\u5B58;\u6CA1\u6709\u81EA\u52A8\u521B\u5EFA\u8868\u683C,\u5143\u6570\u636E\u542B\u4E49\u6216\u79D1\u5B66\u65AD\u8A00.",
    "v0616.conversionBlocked": "\u9057\u5B58 Word \u6587\u672C\u9884\u89C8\u4E0D\u53EF\u7528; \u51C6\u786E\u7684\u539F\u59CB\u4FDD\u7559 \u3002",
    "v0616.error.DOC_ENCRYPTED": "\u6B64\u6587\u6863\u662F\u52A0\u5BC6\u6216\u6A21\u7CCA\u7684\u3002 \u672A\u5C1D\u8BD5\u5BC6\u7801\u6216\u56DE\u6536; \u4FDD\u5B58\u548C\u5BA1\u67E5\u539F\u4EF6 \u3002",
    "v0616.error.DOC_CONTAINER": "\u6B64 OLE \u5BB9\u5668\u635F\u574F\u6216\u8D85\u51FA\u652F\u6301\u7684\u7248\u672C 3 \u5BB9\u5668\u5B50\u96C6\u3002 \u539F\u59CB\u5185\u5BB9\u4FDD\u7559 \u3002",
