    "v0616.error.DOC_TEXT": "\u4E3B\u697C\u6587\u5B57\u4E0D\u5B8C\u6574\u6216\u65E0\u6548,\u6CA1\u6709\u66FF\u6362\u5B57\u7B26\u6216\u90E8\u5206\u6062\u590D\u3002",
    "v0616.error.DOC_LIMIT": "\u8BE5\u6587\u4EF6\u8D85\u8FC7\u4E86\u5B8C\u5168\u6536\u56DE\u9650\u989D,\u786E\u5207\u7684\u539F\u4EF6\u4ECD\u7136\u662F\u4F50\u8BC1\u8BC1\u636E\u3002",
    "v0616.error.DOC_INVALID": "\u6587\u6863\u635F\u574F\u6216\u4E0D\u652F\u6301, \u4E0D\u4E3B\u5F20\u6062\u590D\u6587\u672C \u3002",
    "v0616.error.DOC_BUSY": "\u4E24\u4E2A\u6587\u4EF6\u68C0\u67E5\u6863\u7E41\u5FD9,\u91CD\u8BD5\u68C0\u67E5;\u539F\u7269\u4FDD\u5B58\u5B8C\u597D.",
