    "v0616.error.DOC_MEMORY_LIMIT": "\u6587\u6863\u9605\u8BFB\u5668\u8D85\u8FC7\u4E86\u5176\u5185\u5B58\u9650\u5236, \u51C6\u786E\u7684\u539F\u59CB\u4FDD\u5B58 \u3002",
    "v0616.error.DOC_TIMEOUT": "\u6587\u4EF6\u9605\u8BFB\u5668\u5DF2\u8FBE\u65F6\u9650,\u539F\u7269\u4FDD\u5B58\u5B8C\u597D\u3002",
    "v0616.error.DOC_WORKER_FAILED": "\u5DF2\u7ED1\u5B9A\u7684\u6587\u6863\u9605\u8BFB\u5668\u505C\u6B62, \u6CA1\u6709\u5B8C\u6574\u7684\u7ED3\u679C\u3002 \u539F\u59CB\u5185\u5BB9\u4FDD\u7559\u4E0B\u6765 \u3002",
    "v0616.error.DOC_OUTPUT_LIMIT": "\u6536\u56DE\u7684\u8BC1\u636E\u8D85\u8FC7\u7ED3\u679C\u9650\u5EA6,\u6CA1\u6709\u58F0\u79F0\u90E8\u5206\u6536\u56DE\u3002",
