    "v0617.identifierColumn": "\u5F15\u7528\u6807\u8BC6\u7B26\u5B57\u6BB5( \u53EF\u9009)",
    "v0617.release": "\u53C2\u8003\u6587\u672C\u3001\u5F15\u6587\u548C\u7ECF\u5BA1\u67E5\u7684\u89E3\u91CA\u8303\u56F4",
    "v0617.bounds": "\u5F15\u7528\u9650\u5236: 1\u4E07\u884C\u548C2 000 000 \u4E2A\u5B57\u7B26\u5355\u5143\u8DE8\u8D8A\u9009\u5B9A\u5B57\u6BB5; \u5B8C\u6574\u5F15\u7528\u88AB\u68C0\u67E5, \u800C\u4E0D\u662F\u91C7\u6837\u3002 \u7A7A\u7684\u6216\u6A21\u68F1\u4E24\u53EF\u7684\u5339\u914D\u4FDD\u7559\u4E86\u8BB0\u5F55\u7684\u540D\u79F0, \u5E76\u7559\u4E0B\u6240\u751F\u6210\u7684\u6807\u8BC6\u7B26\u7A7A\u767D \u3002 \u590D\u5236\u7684\u76F8\u540C\u540D\u79F0/ \u6807\u8BC6\u7B26\u5019\u9009\u4EBA\u540C\u610F; \u4E0D\u540C\u7684\u5BF9\u4ECD\u7136\u76F8\u4E92\u51B2\u7A81 \u3002 \u9009\u5B9A\u4F46\u7A7A\u7684\u6807\u8BC6\u7B26\u5C1A\u672A\u89E3\u51B3 \u3002",
    "v0617.noIdentifierColumn": "\u4E0D\u83B7\u53D6\u5F15\u7528\u6807\u8BC6\u7B26",
    "v0617.chooseField": "\u9009\u62E9\u5B57\u6BB5",
    "v0617.candidates": "\u5730\u65B9\u5206\u7C7B\u5019\u9009\u4EBA",
    "v0617.candidateSafety": "\u8FD9\u4E9B\u6587\u5B57\u5F15\u7528\u6761\u76EE\u662F\u60A8\u6240\u9009\u62E9\u7684\u516C\u7EA6\u7684\u5019\u9009\u6761\u76EE\u3002\u5B83\u4EEC\u7684\u5B58\u5728\u5E76\u4E0D\u80FD\u786E\u5B9A\u5F53\u524D\u7684\u5206\u7C7B\u5B66\u3001\u751F\u7269\u7279\u5F81\u6216\u6743\u5A01\u63A5\u53D7\u6027\u3002\u9884\u89C8\u663E\u793A\u6700\u591A10\u4E2A\u89C2\u5BDF\u5B9E\u4F8B,\u6BCF\u4E2A\u89C2\u5BDF\u5B9E\u4F8B\u67095\u4E2A\u5019\u9009\u4EBA;\u8BA1\u6570\u6DB5\u76D6\u6BCF\u4E00\u9879\u89C2\u5BDF\u3002",
