    "v06.preserveAndReview": "\u30D5\u30A1\u30A4\u30EB\u306E\u4FDD\u5B58\u3068\u30EC\u30D3\u30E5\u30FC\u306E\u63D0\u6848",
    "v06.importProjectChanged": "\u9078\u629E\u3057\u305F\u30D7\u30ED\u30B8\u30A7\u30AF\u30C8\u306F\u3001\u767A\u898B\u4E2D\u306B\u5909\u66F4\u3055\u308C\u307E\u3057\u305F\u3002 \u30AD\u30E3\u30F3\u30BB\u30EB\u3057\u3066\u3001\u9593\u9055\u3063\u305F\u30D7\u30ED\u30B8\u30A7\u30AF\u30C8\u306B\u30A4\u30F3\u30DD\u30FC\u30C8\u3092\u907F\u3051\u308B\u305F\u3081\u306B\u518D\u3073\u958B\u59CB\u3057\u307E\u3059\u3002",
    "v06.helpSearch": "\u30D8\u30EB\u30D7\u3068\u7528\u8A9E\u96C6\u3092\u691C\u7D22",
    "v06.helpExplanation": "\u660E\u767D\u306A\u8A00\u8A9E\u8AAC\u660E\u3092\u898B\u3064\u3051\u3066\u4E0B\u3055\u3044\u3002\u6280\u8853\u7684\u306A\u8A00\u8449\u306F\u3042\u306A\u305F\u304C\u4F7F\u7528\u3059\u308B\u30EF\u30FC\u30AF\u30B9\u30DA\u30FC\u30B9 \u30D7\u30ED\u30D5\u30A3\u30FC\u30EB\u304C\u540C\u3058\u79D1\u5B66\u30E2\u30C7\u30EB\u3092\u3001\u8A18\u8FF0\u3057\u307E\u3059\u3002",
