    "ui.81a0210061e8": "\uC8FC\uC694 \uD2B9\uC9D5 CSV \uC5F0\uAD6C\uBD84\uC57C",
    "ui.9397cabc5b02": "\uC774 \uCEF4\uD4E8\uD130\uC5D0\uC11C \uC800\uC7A5\uB41C \uD504\uB85C\uC81D\uD2B8",
    "ui.d8e10cd7845b": "Manifests \uBC0F \uC6D0\uB798 \uBC14\uC774\uD2B8\uB294 \uD504\uB85C\uC81D\uD2B8\uC758 \uB85C\uCEEC \uB370\uC774\uD130 \uD3F4\uB354\uC5D0 \uC0B4\uACE0 \uC788\uC2B5\uB2C8\uB2E4. \uB2E4\uB978 \uC7A5\uCE58\uC5D0 \uD734\uB300\uC6A9 \uBC31\uC5C5\uC744 \uC720\uC9C0\uD558\uC2ED\uC2DC\uC624.",
    "ui.c804d660ca01": "PRESERVE MEANING. UNCERTAINTY VISIBLE\uC5D0 \uCC38\uAC00.",
    "ui.7449dc81f87c": "\uB370\uC774\uD130 \uBCF5\uAD6C.",
    "ui.0525647d91ef": "\uC99D\uAC70 \uC720\uC9C0.",
    "ui.3783dfbdde65": "OFFLINE \xB7 IMMUTABLE ORIGINALS \xB7 EVIDENCE & PROVENANCE",
    "ui.be25b74da408": "biodiversity \uB370\uC774\uD130 \uAD6C\uC870\uC5D0 \uC0C8\uB85C\uC6B4?",
    "ui.327414c7f308": "\uAD6C\uC870\uB294 \uB370\uC774\uD130\uB97C \uBCF4\uC874\uD558\uACE0 \uC0AC\uC6A9\uD560 \uC218\uC788\uB294 \uCEE8\uD14D\uC2A4\uD2B8\uB97C \uBCF5\uAD6C\uD558\uB294 \uAC83\uC744 \uC758\uBBF8\uD569\uB2C8\uB2E4 : \uD544\uB4DC \uC815\uC758, \uB2E8\uC704, \uC0D8\uD50C\uB9C1 \uB178\uB825, \uD504\uB85C\uD1A0\uCF5C \uBC0F \uC99D\uAC70. \uD30C\uC77C\uB85C \uC2DC\uC791\uD558\uAC70\uB098 \uC77C\uD68C\uC6A9 \uD53C\uC158 \uB370\uC774\uD130 \uC138\uD2B8\uC640 \uC5F0\uC2B5.",
