    "ui.f05a9541d508": "\uB0B4\uAD6C\uC131",
    "ui.d73407ac9a2d": "\uC190\uC0C1\uB41C \uBCC0\uD654\uB294 \uB514\uC2A4\uD06C\uC5D0 autosave. \uC774\uC804\uC758 \uD45C\uC2DC \uAC1C\uC815\uC740 \uBCF5\uAD6C\uB97C \uC9C0\uC6D0\uD569\uB2C8\uB2E4. \uC6D0\uBCF8\uC740 \uB0B4\uC6A9 \uCDE8\uAE09\uD558\uACE0 \uACB0\uCF54 rewritten.",
    "ui.c220fd2ec776": "\uB3C5\uB9BD\uC801 \uC778 \uBC31\uC5C5 \uC720\uC9C0 \u2192",
    "ui.4c6fc6a04a22": "protocol_2008.txt",
    "ui.5694d08a2e53": "\uC774\uB984 *",
    "ui.ee0f32af51f4": "\uC624\uD508 \uC18C\uC2A4 \uBC0F \uC77D\uAE30",
    "ui.e836520126d3": ". \uC99D\uAC70\uB294 \uAC01 \uBD84\uC57C\uB97C \uC124\uBA85\uD558\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4.",
    "ui.07b63476df85": "\uAD00\uACC4\uC5D0\uC11C \uC81C\uC548 \uB41C obs \u2192 \uC774\uBCA4\uD2B8 \uB9C1\uD06C\uB97C \uAC80\uD1A0\uD558\uC2ED\uC2DC\uC624. \uC774\uBCA4\uD2B8 \uC2DD\uBCC4\uC790\uB85C event_id\uB97C \uD655\uC778\uD558\uC2ED\uC2DC\uC624. E404 \uBC0F unsampled E03 \uC774\uBCA4\uD2B8\uB97C \uAC80\uC0AC\uD558\uC2ED\uC2DC\uC624.",
    "ui.82b859b47c50": "Metadata\uC5D0\uC11C \uBCF5\uAD6C",
    "ui.f8682f8c115b": "\uD504\uB85C\uD1A0\uCF5C\uC5D0 \uAE30\uC220\uB41C \uC2DC\uAC01\uC801\uC778 \uC870\uC0AC\uB85C. \uC0C1\uD0DC \uD655\uC778 \uBC0F \uC99D\uAC70\uB85C \uADF8 \uC758\uC815\uC11C\uB97C \uBD99\uC774\uAE30. \uACC4\uC18D\uD558\uC2ED\uC2DC\uC624",
    "ui.9cf9f50925b2": "\uC774\uB984 *",
    "ui.ff910fb28c15": "\uC218\uB9AC, \uBBF8\uB9AC\uBCF4\uAE30 \uD2B8\uB9AC\uBC0D \uBC31\uC2A4\uD398\uC774\uC2A4. \uADF8\uAC83\uC744 \uC815\uC0C1\uD654\uD558\uAE30 \uC804\uC5D0 NA \uCEE8\uBCA4\uC158\uC744 \uD655\uC778; 0\uC758 \uCC28\uC774\uB97C \uC720\uC9C0.",
    "ui.c0b1f0e7587c": "ambiguous \uB0A0\uC9DC\uC640 \uBD88\uAC00\uB2A5\uD55C \uC88C\uD45C\uB97C \uAC80\uD1A0\uD558\uC2ED\uC2DC\uC624. \uD504\uB85C\uD1A0\uCF5C\uC740 \uB85C\uCEEC \uB610\uB294 datum\uC744 \uCD94\uCE21\uD558\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4.",
    "ui.8dab7ac43643": "\uAC80\uC99D \uBC0F \uB0B4\uBCF4\uB0B4\uAE30 \uBCF4\uC874 \uD328\uD0A4\uC9C0. \uADF8\uB7F0 \uB2E4\uC74C \uC870\uC815 \uB41C \uACF5\uACF5 \uD328\uD0A4\uC9C0\uB97C \uD14C\uC2A4\uD2B8\uD569\uB2C8\uB2E4.",
    "ui.41cf6794ba42": "\uC774\uB984 *",
    "ui.2a0950b20037": "\uC99D\uAC70\uB85C \uC77D\uAE30 \u2192",
