    "ui.a5e76043b437": "\uC815\uD655\uD55C \uD544\uB4DC \uC774\uB984\uC740 \uBAA8\uB450 \uC874\uC7AC\uD574\uC57C\uD569\uB2C8\uB2E4.",
    "ui.a7d7ff92498b": "\uC774 \uAD00\uACC4\uB294 \uC774\uBBF8 \uC874\uC7AC\uD55C\uB2E4.",
