    "ui.465dd58520e9": "\uC774 \uC791\uC5C5\uC744 \uBBF8\uB9AC \uBCF4\uAE30 \uC804\uC5D0 \uD569\uB9AC\uC801 \uC81C\uACF5.",
    "ui.0caf91617a79": "{p0} \uC601\uD5A5\uC744\uBC1B\uB294 \uD589 / \uC774\uB984",
    "ui.75fc8393dfa5": "\uD604\uC7AC \uD14C\uC774\uBE14\uC5D0 \uB300\uD55C\uC774 \uC791\uC5C5\uC744 \uBBF8\uB9AC\uBCF4\uAE30.",
    "ui.bc2e873e153d": " \xB7 {p0} \xB7 {p1} heuristic \uC2E0\uB8B0",
    "ui.70f84be70c4a": "{p0} \uC18C\uC2A4 \uD30C\uC77C; {p1} \uD14C\uC774\uBE14; {p2} \uAD00\uACC4.",
    "ui.d543deb6b512": "{p0} \uD574\uACB0 \uB41C \uC9C4\uB2E8 \uD56D\uBAA9. \uC218\uCD9C \uB41C \uBCF4\uACE0\uC11C\uC5D0\uB294 \uD30C\uC77C \uCCB4\uD06C\uC12C, \uD544\uB4DC \uB808\uBCA8 \uBD88\uD655\uC2E4\uC131, \uAD00\uACC4, \uC99D\uAC70, \uC218\uB9AC, \uD45C\uC900 \uAE30\uB2A5 \uBC0F \uAD8C\uC7A5 \uB098\uBA38\uC9C0 \uC791\uC5C5\uC744 \uD3EC\uD568\uD569\uB2C8\uB2E4.",
    "ui.b9c92400cf83": "\uD30C\uC77C \uC0AD\uC81C \uB610\uB294 \uAC80\uC0C9\uC744 \uD074\uB9AD\uD569\uB2C8\uB2E4",
    "ui.8ff654c3e225": "\uBCF4\uC874 \uC18C\uC2A4 \uBC0F \uB9AC\uC18C\uC2A4 \uCD94\uAC00 \u2192",
    "ui.68605593ee77": "\uC18C\uC2A4\uB294 20 MiB\uB97C \uCD08\uACFC\uD569\uB2C8\uB2E4.",
    "ui.c7f39314ace9": "\uC0C1\uC18D\uB41C \uC18C\uC2A4 \uD30C\uC77C\uC744 \uC120\uD0DD\uD558\uC2ED\uC2DC\uC624.",
