    "ui.e32bb59f55c3": "Active Work, \uC544\uCE74\uC774\uBE0C \uD504\uB85C\uC81D\uD2B8 \uBC0F \uBCF5\uAD6C \uC0AC\uBCF8\uC744 \uCC3E\uC744 \uC218 \uC788\uB3C4\uB85D \uD504\uB85C\uC81D\uD2B8 \uC5F4\uAE30.",
    "ui.93e1e1234a43": "\uC791\uC5C5 \uC601\uC5ED \uBAA8\uB4DC \uC120\uD0DD",
    "ui.202c3e907b32": "Beginner\uB294 \uC791\uC5C5 \uD750\uB984\uC744 \uC124\uBA85\uD569\uB2C8\uB2E4. \uC804\uBB38\uAC00\uB294 \uC815\uD655\uD55C \uC2A4\uD0A4\uB9C8 \uBC0F \uAE30\uC220 \uC138\uBD80 \uC0AC\uD56D\uC744 \uB178\uCD9C\uD569\uB2C8\uB2E4. \uACFC\uD559 \uD504\uB85C\uC81D\uD2B8\uB294 \uB3D9\uC77C\uD558\uAC8C \uC720\uC9C0\uB429\uB2C8\uB2E4. \uACC4\uC18D \uBAA8\uB4DC\uB97C \uC120\uD0DD\uD558\uC2ED\uC2DC\uC624.",
    "ui.3f940108cb1e": "\uC124\uC815 \uC5F4\uAE30",
    "ui.fc17ed707a8b": "\uC77D\uAE30, \uC678\uAD00 \uBC0F \uB85C\uCEEC \uC800\uC7A5 \uC120\uD638\uB3C4\uB97C \uC870\uC815\uD558\uB294 \uC124\uC815 \uC120\uD0DD.",
    "ui.f27afa06cc0c": "\uAC01 \uC870\uC815\uC744 \uC704\uD55C \uBA85\uD655\uD55C \uC7A5\uC18C",
    "ui.ee3bcd0c35ad": "checkmark\uB97C \uAC00\uC9C4 \uCC44\uC6CC\uC9C4 \uC885\uB958\uB294 \uD604\uC7AC \uB2E8\uBA74\uB3C4\uC785\uB2C8\uB2E4. \uADF8\uAC83\uC758 \uD1B5\uC81C\uB97C \uBCF4\uAE30 \uC704\uD558\uC5EC \uB2E4\uB978 \uC885\uB958\uB97C \uC120\uD0DD\uD558\uC2ED\uC2DC\uC624.",
    "ui.706005c0492d": "\uB2F9\uC2E0\uC758 \uC77C\uC740 \uD604\uC9C0 \uCCB4\uB958",
    "ui.e4b4f29230d8": "\uC0C1\uD0DC\uB294\uC774 \uC791\uC5C5 \uACF5\uAC04\uC744 \uC124\uBA85\uD569\uB2C8\uB2E4. \uB370\uC774\uD130\uB294\uC774 \uC7A5\uCE58\uC5D0\uC11C \uCC98\uB9AC\uB429\uB2C8\uB2E4. \uC218\uCD9C \uC900\uBE44\uB294 \uC790\uB3D9\uC73C\uB85C \uAC8C\uC2DC\uB418\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4.",
    "ui.27c67c8371f6": "\uC624\uB798\uB41C dataset\uC5D0\uC11C \uAC00\uC838\uC635\uB2C8\uB2E4",
    "ui.3e4ba6549477": "dataset\uB97C \uAC00\uC838\uC635\uB2C8\uB2E4. \uB2F9\uC2E0\uC740 \uADF8\uAC83\uC744 \uBCF4\uC874\uD558\uAE30 \uC804\uC5D0 \uD30C\uC77C\uC744 \uC77D\uB294 \uBC29\uBC95\uC744 \uAC80\uC5F4\uD560 \uAC83\uC785\uB2C8\uB2E4.",
    "ui.6a85d53279b1": "\uC5EC\uAE30\uB97C \uD074\uB9AD\uD558\uAC70\uB098 \uB4DC\uB86D",
