    "ui.ce8079e943b0": "\uC774 fictional Rocky Mountain amphibian \uCEEC\uB809\uC158\uC5D0\uB294 \uCDA9\uB3CC \uAE30\uB85D\uC774 \uD3EC\uD568\uB418\uC5B4 \uC788\uC2B5\uB2C8\uB2E4. \uC9C4\uD589\uC740 \uC778\uC99D\uC774 \uC544\uB2D9\uB2C8\uB2E4.",
    "ui.caf85b0888d7": "\uC774\uB984 *",
    "ui.1c3d7920ed11": "\uC0AC\uC804\uC608\uC57D",
    "ui.4b60e17cdc89": "\uBAA8\uB4E0 \uC6D0\uBCF8 \uD30C\uC77C\uACFC \uCCB4\uD06C\uC12C\uC744 \uD655\uC778\uD569\uB2C8\uB2E4. \uC791\uC5C5 \uD3B8\uC9D1\uC740 \uC18C\uC2A4 \uBC14\uC774\uD2B8\uB97C \uB300\uCCB4\uD558\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4.",
    "ui.bbc961ca7f59": "\uC774\uC804 \uC77D\uAE30",
    "ui.2d059392988a": "\uC81C\uD488\uC815\uBCF4 README_old.txt. unquestionable\uB85C \uC624\uB798\uB41C \uBB18\uC0AC\uB97C \uB300\uC6B0\uD558\uAE30 \uBCF4\uB2E4\uB294 \uC624\uD788\uB824 \uAE30\uB85D uncertainty.",
    "ui.04a1047c8d69": "3\uAC1C\uC758 \uCD5C\uC885 \uAD50\uACFC\uC11C \uBE44\uAD50",
    "ui.b1c9bb437b89": "\uB354 \uBCF4\uAE30 survey_FINAL.xlsx\xB7 survey_FINAL2.xlsx \uC774\uB984 * survey_FINAL_FIXED.xlsx. \uD30C\uC77C\uBA85\uC740 \uAD8C\uD55C\uC744 \uC124\uC815\uD558\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4.",
    "ui.94e01e0ca8ec": "Inspect \uD14D\uC2A4\uD2B8 \uCEE8\uBCA4\uC158",
    "ui.06f287336908": "delimiter, \uC778\uCF54\uB529, \uD5E4\uB354 \uD589 \uBC0F \uB9AC\uD130\uAC12\uC744 \uAC80\uD1A0\uD569\uB2C8\uB2E4. \uC131\uACF5\uC801\uC778 \uD30C\uC2A4\uB294 \uD574\uC11D\uC744 \uC99D\uBA85\uD558\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4.",
    "ui.617c4ac2a909": "\uC790\uC8FC \uBB3B\uB294 \uC9C8\uBB38",
    "ui.1cfc17965af7": "\uAD00\uCC30, \uC774\uBCA4\uD2B8, \uC885 \uBD80\uD638 \uBC0F \uB0A0\uC528\uB97C \uC120\uD0DD\uD558\uC2ED\uC2DC\uC624. \uD45C\uB294 \uBA85\uBC31\uD55C \uACE1\uBB3C\uC774 \uC788\uC2B5\uB2C8\uB2E4.",
    "ui.6afeb56acf53": "\uBD88\uC644\uC804\uD55C",
    "ui.b4e4f0784812": "\uD504\uB85C\uD1A0\uCF5C\uC774 \uC758\uBBF8\uB97C \uC815\uC758\uD560 \uB54C\uAE4C\uC9C0 \uACF5\uBC31, NA, Zero \uBC0F \uBD80\uC7AC\uB97C \uC9C0\uD0A4\uC2ED\uC2DC\uC624.",
    "ui.9eddf573cb50": "\uBA54\uD0C0\uB370\uC774\uD130",
    "ui.b3821b7bfaef": "Recover a field \uC758\uBBF8",
    "ui.61692a6d4095": "\uC9C0\uC6D0\uD558\uB2E4 protocol_REVISED.txt \uACC4\uC0B0 \uD544\uB4DC n\uC744 \uBB38\uC11C\uD654 \uD560 \uB54C \uC99D\uAC70\uB85C \uCCA8\uBD80\uD569\uB2C8\uB2E4.",
    "ui.03867aea70ac": "\uC9C0\uC6D0\uD558\uB2E4",
    "ui.5a3a9f9edd17": "\uBCF4\uC0C1 \uBC1B\uAE30",
    "ui.2355763d74cc": "\uCF54\uB4DC\uC758 \uC758\uBBF8\uB97C \uBAA8\uB450 \uAE30\uB85D 4 \uBCC4\uB3C4\uC758 assertions. \uC870\uC6A9\uD788 \uD558\uB098\uB97C \uC120\uD0DD\uD558\uC9C0 \uB9C8\uC2ED\uC2DC\uC624.",
    "ui.7d7334ca475c": "mystery \uC54C \uC218 \uC5C6\uB294 \uAC83",
    "ui.04faeebabc4b": "unexplained \uD544\uB4DC\uB294 \uC54C \uC218 \uC5C6\uC2B5\uB2C8\uB2E4. \uCD94\uCE21\uC740 \uD569\uB9AC\uC801 \uC778\uC73C\uB85C \uAE30\uB85D \uB420 \uC218 \uC788\uC2B5\uB2C8\uB2E4.",
    "ui.7bc88ab890e9": "\uBB38\uC11C \uC77C\uC815",
    "ui.8716ace2f7f6": "ambiguous \uAC12\uC5D0\uC11C \uC6D4\uCD08 \uB610\uB294 \uC77C\uCD08\uB97C \uC120\uD0DD\uD558\uC9C0 \uB9C8\uC2ED\uC2DC\uC624. \uBD80\uBD84\uC801\uC778 \uB0A0\uC9DC\uB294 \uADF8\uB4E4\uC758 \uC815\uBC00\uB3C4\uB97C \uC720\uC9C0\uD569\uB2C8\uB2E4.",
    "ui.7aa7675978e1": "\uBE44\uBC00\uBC88\uD638",
    "ui.5e366c81d210": "\uC88C\uD45C\uB294 \uCC38\uC870 \uC2DC\uC2A4\uD15C \uBC0F datum\uC774 \uD544\uC694\uD569\uB2C8\uB2E4. \uC54C \uC218\uC5C6\uB294 \uCEE8\uD14D\uC2A4\uD2B8\uB294 \uBCFC \uC218 \uC788\uC2B5\uB2C8\uB2E4.",
    "ui.85752a46aa46": "\uAD00\uACC4",
    "ui.47063ae8052e": "\uC774\uBCA4\uD2B8 \uC2DD\uBCC4\uC790 \uAC80\uD1A0",
    "ui.7954e4881c47": "\uC99D\uAC70\uB9CC \uC2DD\uBCC4\uC790\uB97C \uACB0\uC815\uD569\uB2C8\uB2E4. \uB4DC\uB86D\uB9C1 \uB808\uCF54\uB4DC\uBCF4\uB2E4\uB294 \uC911\uBCF5 E2\uB97C \uAC80\uC0AC\uD569\uB2C8\uB2E4.",
    "ui.100f806b2d6f": "\uAC80\uC0AC orphan \uAD00\uCE21",
    "ui.ff556abd2a06": "Investigate E404 \uBC0F \uB204\uB77D\uB41C \uBD80\uBAA8 \uC0AC\uAC74. \uAC74\uC758\uD55C \uC5F0\uACB0\uC740 \uC99D\uAC70\uB97C \uD655\uC778\uD558\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4.",
    "ui.b7060b82523f": "\uBE44\uAC80\uCD9C",
    "ui.a212ffaffe25": "\uAD00\uCC30\uC5C6\uC774 \uC774\uBCA4\uD2B8\uB294 \uC124\uBB38 \uC870\uC0AC \uB178\uB825\uC744 \uAE30\uB85D \uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4. \uB370\uC774\uD130\uB97C \uB204\uB77D\uD558\uC9C0 \uB9C8\uC2ED\uC2DC\uC624.",
    "ui.f187f78e07ef": "\uC2A4\uB0C5\uC0F7",
    "ui.a94cb6638217": "\uC790\uC8FC \uBB3B\uB294 \uC9C8\uBB38",
    "ui.6fe7ca22548f": "\uC218\uB9AC \uC804\uC5D0 \uCCB4\uD06C \uD3EC\uC778\uD2B8\uB97C \uC720\uC9C0; \uB610\uD55C \uB3C5\uB9BD\uC801 \uC778 \uD734\uB300\uC6A9 \uBC31\uC5C5\uC744 \uC218\uCD9C.",
    "ui.1196b6c538ec": "\uC81C\uD488 \uC815\uBCF4",
    "ui.99d284f5e386": "\uBBF8\uB9AC\uBCF4\uAE30 whitespace \uC218\uB9AC",
    "ui.bd31838fe77e": "\uD2B8\uB9AC\uB97C \uC801\uC6A9\uD558\uAE30 \uC804\uC5D0 \uC601\uD5A5\uC744\uBC1B\uB294 \uAC12\uC744 \uC77D\uC73C\uC2ED\uC2DC\uC624. \uBAA8\uB4E0 \uC758\uBBF8\uC788\uB294 \uBCC0\uD654\uB294 \uC774\uC720\uAC00 \uD544\uC694\uD569\uB2C8\uB2E4.",
    "ui.7cefb7bd4bec": "\uB204\uB77D\uAC12 \uC815\uC0C1\uD654 \uAC80\uD1A0",
    "ui.6edd544ccdd9": "\uB9AC\uD130\uB7F4 \uCF54\uB4DC\uB97C \uBCC0\uACBD\uD558\uAE30 \uC804\uC5D0 \uB204\uB77D\uB41C \uAC12\uC744 \uC9C0\uC815\uD569\uB2C8\uB2E4. Zero\uB294 \uCE21\uC815\uC785\uB2C8\uB2E4.",
    "ui.f99cdbcfb11b": "\uAC10\uC0AC/\uBCF4\uACE0\uC11C",
    "ui.d59a496772aa": "\uAC10\uC0AC \uD2B8\uB808\uC77C \uAC80\uC0AC",
    "ui.aae3638356fb": "Undo and redo add event. \uB808\uC2DC\uD53C\uB294 \uC18C\uC2A4\uB97C \uC7AC\uC0DD\uD558\uACE0 \uBCC4\uB3C4\uC758 \uD504\uB85C\uC81D\uD2B8\uB97C \uB9CC\uB4ED\uB2C8\uB2E4.",
    "ui.13e4912a22c8": "\uD45C\uC900\uC5D0 \uC9C0\uB3C4",
    "ui.0e964574cd97": "\uC81C\uC548 \uB41C \uB9E4\uD551\uC744 \uAC80\uD1A0",
    "ui.9bf00ee8a526": "\uC6A9\uC5B4 \uC81C\uC548\uC740 \uD6C4\uBCF4\uC790\uC785\uB2C8\uB2E4. \uD45C\uC900 \uC218\uCD9C \uC804\uC5D0 \uC758\uBBF8\uC640 \uC99D\uAC70\uB97C \uD655\uC778\uD558\uC2ED\uC2DC\uC624.",
    "ui.40611abbdda2": "\uC774\uB984 *",
    "ui.1550feedfa51": "\uC790\uC8FC \uBB3B\uB294 \uC9C8\uBB38",
