    "ui.d790125e304e": "\uBE44\uAC80\uCD9C",
    "ui.2d81168dd599": "\uB300\uC0C1\uC744 \uAC10\uC9C0\uD558\uC9C0 \uC54A\uC740 \uBB38\uC11C \uAC80\uC0C9; \uADF8\uAC83\uC740 \uC124\uBB38 \uC870\uC0AC \uB178\uB825 \uB9E5\uB77D\uC744 \uD544\uC694\uB85C\uD55C\uB2E4.",
    "ui.d5e35696071e": "\uBD88\uD655\uC2E4\uD55C\uACFC \uB354\uBD88\uC5B4 \uC99D\uAC70\uC5D0 \uC758\uD574 \uC81C\uC548\uB41C \uD574\uC11D.",
