    "msg.ee7e4988916d": "\uC120\uC5B8 \uB41C \uAD00\uACC4\uB294 \uB9AC\uBDF0 \uC81C\uACF5 \uC5C5\uCCB4\uC640 \uB2E4\uB985\uB2C8\uB2E4. \uC815\uCCB4\uC131\uACFC \uC678\uAD6D \uD0A4 \uB9E4\uD551\uC744 \uAC80\uD1A0\uD558\uC2ED\uC2DC\uC624.",
    "msg.39dc06e9b5d1": "\uD0C0\uAC9F \uD544\uB4DC\uB294\uC774 \uC5F4\uC758 \uD655\uC778 \uB41C \uC6A9\uC5B4 \uD574\uC11D\uACFC \uC77C\uCE58\uD574\uC57C\uD569\uB2C8\uB2E4.",
    "msg.0630a94b1bae": "\uC120\uC5B8 \uB41C \uC2DD\uBCC4\uC790\uB294 \uB9AC\uBDF0 \uACF5\uAE09\uC790 \uAE30\uBCF8 \uD0A4\uC640 \uC77C\uCE58\uD558\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4.",
    "msg.b7906c912394": "\uAC80\uD1A0 \uD14C\uC774\uBE14\uC740 \uB9F5\uD551\uB418\uC9C0 \uC54A\uC740 \uC2DD\uBCC4\uC790 \uD544\uB4DC\uAC00 \uD544\uC694\uD569\uB2C8\uB2E4.",
    "msg.b52da33f57cf": "Ephemeral \uD3B8\uC9D1 \uAD8C\uC704\uB294 \uD2BC\uD2BC\uD55C \uACFC\uD559\uC801\uC778 \uAC1C\uC815 \uCCB4\uD06C\uB97C \uBCF4\uCDA9\uD569\uB2C8\uB2E4.",
    "msg.59d2a4851582": "\uAC1C\uBC29\uD615 \uBA40\uD2F0 \uB9AC\uC18C\uC2A4 \uD328\uD0A4\uC9C0. \uACF5\uACF5 \uC218\uCD9C\uC740 \uC6D0\uB798 \uB610\uB294 \uAC10\uC0AC \uC2A4\uB0C5 \uC0F7\uC744 \uD3EC\uD568\uD558\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4.",
