    "msg.455313462703": "Truncated DBF \uD5E4\uB354.",
    "msg.1b6c6ef61e3d": "\uC798\uBABB\uB41C DBF \uCE58\uC218 \uB610\uB294 \uC81C\uD55C\uC774 \uCD08\uACFC\uB418\uC5C8\uC2B5\uB2C8\uB2E4.",
    "msg.41b4845690d8": "DBF \uB808\uCF54\uB4DC \uB808\uC774\uC544\uC6C3 \uC9C0\uC6D0.",
    "msg.9810937f6a4e": "Geometry\uB294 \uB9AC\uD130\uB7F4\uB85C \uC720\uC9C0 JSON; CRS assumption, reprojection \uB610\uB294 inferred \uD611\uC870 \uBD84\uC57C \uC5C6\uC74C.",
    "msg.36566cc5d217": "Truncated DBF \uD544\uB4DC \uB514\uC9C0\uD130.",
    "msg.0bfcfc1ecbcf": "\uC0AD\uC81C \uB41C \uB808\uCF54\uB4DC \uC720\uC9C0 \uBC0F \uBD99\uC5EC \uB123\uAE30. \uBB38\uC790 / \uC22B\uC790 / \uB0A0\uC9DC \uAC12\uC740 \uB9AC\uD130\uB7F4 \uC720\uC9C0; hex \uD3EC\uC778\uD130\uB85C \uD45C\uD604 \uB41C \uBA54\uBAA8 / \uBE48 \uD544\uB4DC\uB294 \uBCC4\uB3C4\uB85C \uBCF4\uC874\uD574\uC57C\uD569\uB2C8\uB2E4. \uC790\uB3D9 \uC778\uCF54\uB529\uC740 Windows-1252, \uBA85\uC2DC\uC801 \uAC80\uD1A0 \uAC00\uB2A5\uD55C \uAC00\uC815\uC785\uB2C8\uB2E4.",
    "msg.ceaaaa048670": "\uCEE8\uD14C\uC774\uB108 \uC7AC\uACE0 \uB9CC. \uD68C\uC6D0\uC774 \uC2E4\uD589\uB418\uAC70\uB098 \uCD94\uCD9C\uB418\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4. \uC6D0\uB798 \uC544\uCE74\uC774\uBE0C \uBCF4\uC874.",
    "msg.18beb6137b41": "\uBC84\uC804 \uC218\uC785 \uC5B4\uB311\uD130. \uC9C0\uC6D0\uB418\uC9C0 \uC54A\uC740 \uBC14\uC774\uD2B8\uB294 \uC99D\uAC70 \uB9AC\uC18C\uC2A4\uB85C \uBCF4\uC874\uB429\uB2C8\uB2E4.",
    "msg.0804e3b2cb98": "SQLite\uB294 \uC77D\uAE30 \uC804\uC6A9\uC744 \uC218\uC785\uD588\uC2B5\uB2C8\uB2E4. \uC870\uD68C / \uD2B8\uB9AC\uAC70\uAC00 \uC2E4\uD589\uB418\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4. Blob \uAC12\uC740 base64 \uD14D\uC2A4\uD2B8\uB85C \uC720\uC9C0\uB429\uB2C8\uB2E4. GeoPackage \uAE30\uD558\uD559\uC740 \uBCF4\uC874\uB418\uC9C0 \uC54A\uC73C\uBA70 \uB9E4\uD551\uB418\uAC70\uB098 \uBCC0\uD658\uB418\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4.",
    "msg.a76ee854c3c9": "\uAC10\uC555\uC5C6\uC774 \uC9C0\uC6D0\uB418\uB294 \uC99D\uAC70\uB85C \uBCF4\uC874.",
    "msg.d4ad6ec3d1e5": "\uC774 \uCCB4\uC7AC\uB97C \uC704\uD55C tabular \uC811\uD569\uAE30 \uC5C6\uC74C. \uC9C0\uC6D0 \uC790\uC6D0\uC73C\uB85C \uBCF4\uC874\uD558\uB294; \uACFC\uD559\uC801\uC778 \uB9E5\uB77D \uC5C6\uC74C.",
    "msg.3e9ed08404a9": "\uC6D0\uB798 \uBC14\uC774\uD2B8 \uC720\uC9C0; \uCD94\uCD9C\uC740 \uBD88\uC644\uC804 \uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4.",
    "msg.294f8e3fa2a9": "\uD655\uC7A5\uB41C \uC6CC\uD06C\uBD81\uC740 100 MiB\uB97C \uCD08\uACFC\uD569\uB2C8\uB2E4.",
    "msg.f44bd56bd941": "\uD3EC\uB9F7, \uCC28\uD2B8, \uC774\uBBF8\uC9C0, \uC2A4\uB808\uB4DC \uCF54\uBA58\uD2B8, \uD53C\uBC97 \uD14C\uC774\uBE14, \uC678\uBD80 \uB9C1\uD06C \uBC0F \uC784\uBCA0\uB514\uB4DC \uAC1C\uCCB4\uB294 \uC6D0\uB798 \uC6CC\uD06C\uBD81\uC5D0 \uB0A8\uC544; \uD0ED \uB370\uC774\uD130\uB85C \uBCC0\uD658\uB418\uC9C0.",
