    "ui.8e80f091b4ad": "\uB300\uCCB4 \uC6A9\uC5B4 IRI (\uC635\uC158)",
    "ui.3e5e78af0a26": "\uC120\uD0DD\uB41C \uC5B4\uD718\uAC00 \uC6A9\uC5B4\uB97C \uD3EC\uD568\uD558\uC9C0 \uC54A\uB294 \uACBD\uC6B0 \uC804\uCCB4 \uC6A9\uC5B4 URL\uC744 \uC0AC\uC6A9\uD558\uC2ED\uC2DC\uC624. \uC774\uAC83\uC740 \uD574\uC11D\uC744 \uAE30\uB85D\uD569\uB2C8\uB2E4. URL\uC774 fetched\uB294 \uC5C6\uC2B5\uB2C8\uB2E4.",
    "ui.93b5453893f4": "\uD14C\uC774\uBE14 \uC900\uBE44\uD558\uAE30 \uC804\uC5D0 \uAD6C\uC870 \uD504\uB85C\uC81D\uD2B8\uB97C \uC5FD\uB2C8 \uB2E4.",
    "ui.e0613377bdaf": "\uD504\uB85C\uC81D\uD2B8",
    "ui.8d4c90cfa98d": "\uAC1C\uC778 \uB9AC\uBDF0 \uCD08\uC548 ZIP",
    "ui.325e85978ffb": "\uAC00\uC774\uB4DC \uAE30\uBC18 \uAC80\uD1A0 \uCD08\uC548 \uC900\uBE44",
    "ui.ecb03f16d638": "1 \uCC28 \uD0A4\uB294 \uAE30\uB85D\uC744 \uC2DD\uBCC4\uD569\uB2C8\uB2E4. \uC678\uAD6D \uD0A4\uB294 \uB2E4\uB978 \uD14C\uC774\uBE14\uC5D0 \uC2DD\uBCC4\uD558\uB294 \uC5B4\uB9B0\uC774 \uAE30\uB85D\uC744 \uC5F0\uACB0\uD569\uB2C8\uB2E4. \uD6C4\uBCF4 \uB9C1\uD06C\uB294 \uD655\uC778 \uB420 \uB54C\uAE4C\uC9C0 hypotheses\uC785\uB2C8\uB2E4.",
    "ui.c5f3f4619989": "\uC218\uB9AC\uB294 \uC791\uC5C5 \uD14C\uC774\uBE14 \uB9CC \uBCC0\uACBD\uD569\uB2C8\uB2E4. \uB0A0\uC9DC, \uC88C\uD45C \uBC0F \uB2E8\uC704 \uBCC0\uD658\uC740 \uD30C\uC0DD \uB41C \uD544\uB4DC\uB97C \uCD94\uAC00\uD558\uACE0 \uC18C\uC2A4 \uBB38\uC790\uC5F4\uC744 \uBCF4\uC874\uD569\uB2C8\uB2E4. \uBCC0\uD658\uD558\uAE30 \uC804\uC5D0 \uC758\uBBF8\uB97C \uD655\uC778\uD558\uC2ED\uC2DC\uC624.",
    "ui.a6e3f39df788": "Darwin Core biodiversity \uB808\uCF54\uB4DC\uC5D0 \uB300\uD55C \uACF5\uC720 \uC5B4\uD718\uC785\uB2C8\uB2E4. \uBC1C\uC0DD\uC740 \uAD00\uCC30\uC744 \uC124\uBA85\uD569\uB2C8\uB2E4. \uC774\uBCA4\uD2B8\uB294 \uC124\uBB38 \uC870\uC0AC\uB97C \uC124\uBA85\uD569\uB2C8\uB2E4. \uC81C\uC548\uC740 \uC5EC\uAE30\uC5D0 hypotheses, \uD560\uB2F9\uB418\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4.",
    "ui.0a6123d36a12": "Provenance\uB294 \uB370\uC774\uD130\uAC00 \uC640\uC11C \uBB34\uC2A8 \uC77C\uC774 \uC788\uC5C8\uB294\uC9C0\uC758 \uAE30\uB85D\uC785\uB2C8\uB2E4. Undo \uBC0F redo\uB294 \uAC10\uC0AC \uC774\uBCA4\uD2B8\uB97C \uCD94\uAC00\uD569\uB2C8\uB2E4. \uADF8\uB4E4\uC740 \uC5ED\uC0AC\uB97C \uC9C0\uC6B0\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4.",
    "ui.0f9d819a7a7f": "\uD3B8\uC9D1 \uD589 {row}\xB7 {field}",
