    "v06.anotherTask": "\uB2E4\uB978 \uC791\uC5C5\uC744 \uD45C\uC2DC",
    "v06.noRecommendations": "\uC774 \uBD84\uC11D\uC5D0\uC11C \uB354 \uB9CE\uC740 \uC81C\uC548\uC774 \uC5C6\uC2B5\uB2C8\uB2E4. \uACF5\uC720\uD558\uAE30 \uC804\uC5D0 \uAC80\uC99D \uBC0F \uC218\uCD9C \uC694\uAD6C \uC0AC\uD56D\uC744 \uAC80\uD1A0\uD558\uC2ED\uC2DC\uC624.",
    "v06.analysisCoverage": "\uBD84\uC11D \uB41C \uAC83",
    "v06.sampleCoverage": "\uC0D8\uD50C\uB4DC {sampled} \uC774\uB984 * {total} \uD589. \uC81C\uC548\uC740\uC774 \uC0D8\uD50C\uC744 \uC124\uBA85\uD569\uB2C8\uB2E4; \uAC80\uC99D \uBC0F \uC218\uCD9C\uC740 \uBCC4\uB3C4 \uB0A8\uC544 \uC788\uC2B5\uB2C8\uB2E4.",
    "v06.noAutomaticMeaning": "\uACFC\uD559\uC801 \uC758\uBBF8, \uAD00\uACC4, \uB2E8\uC704, \uB0A0\uC9DC \uB610\uB294 \uC88C\uD45C \uC2DC\uC2A4\uD15C\uC740 \uC790\uB3D9\uC73C\uB85C \uD560\uB2F9\uB418\uC5C8\uC2B5\uB2C8\uB2E4.",
    "v06.analyzing": "\uC9C0\uC5ED \uC791\uC5C5 \uC8FC\uC11D\uC744 \uC77D\uACE0 \uD504\uB85C\uC81D\uD2B8 \uBD84\uC11D ...",
    "v06.queue": "\uB9AC\uBDF0 queue",
    "v06.translation": "\uBC88\uC5ED \uBC0F \uD45C\uC900\uD654",
    "v06.translationExplanation": "\uC624\uB798\uB41C \uB610\uB294 \uB208\uC5D0 \uB744\uB294 \uB370\uC774\uD130\uAC00 \uB354 \uBA85\uD655\uD558\uACE0 \uC7AC\uC0AC\uC6A9 \uAC00\uB2A5\uD55C \uAD6C\uC870\uB85C \uCF2D\uB2C8\uB2E4. \uC6D0\uB798 \uD30C\uC77C\uC740 \uADF8\uB300\uB85C \uC720\uC9C0\uB429\uB2C8\uB2E4. \uAE30\uACC4\uC801 \uC218\uB9AC\uB294 \uBBF8\uB9AC\uBCF4\uAE30\uC785\uB2C8\uB2E4. \uACFC\uD559\uC801 \uD574\uC11D\uC740 \uC81C\uC5B4\uC5D0\uC11C \uC720\uC9C0\uB429\uB2C8\uB2E4.",
    "v06.queueExplanation": "\uD504\uB85C\uC81D\uD2B8\uC5D0\uC11C \uC5B4\uB5A4 \uAD00\uC2EC\uC744 \uAC00\uC9C8\uC9C0 \uAC80\uD1A0\uD558\uC2ED\uC2DC\uC624. \uD574\uACB0\uB418\uC9C0 \uC54A\uC740 \uACB0\uC815\uC744 \uD3EC\uD568\uD558\uC5EC \uC870\uC0AC \uB41C \uAC83\uC744 \uAE30\uB85D\uD558\uC2ED\uC2DC\uC624.",
