    "v06.showMe": "\uB0B4 \uACC4\uC815",
    "v06.reviewDecision": "\uAE30\uB85D \uAC80\uD1A0 \uACB0\uC815",
    "v06.saveLater": "\uB098\uC911\uC5D0 \uC800\uC7A5",
    "v06.technicalDetails": "\uAE30\uC220 \uC815\uBCF4",
    "v06.reviewExplanation": "\uC774 \uC6F9 \uC0AC\uC774\uD2B8\uB294 \uADC0\uD558\uAC00 \uC6F9 \uC0AC\uC774\uD2B8\uB97C \uD0D0\uC0C9\uD558\uB294 \uB3D9\uC548 \uADC0\uD558\uC758 \uACBD\uD5D8\uC744 \uD5A5\uC0C1\uC2DC\uD0A4\uAE30 \uC704\uD574 \uCFE0\uD0A4\uB97C \uC0AC\uC6A9\uD569\uB2C8\uB2E4. \uC774 \uCFE0\uD0A4\uB4E4 \uC911\uC5D0\uC11C \uD544\uC694\uC5D0 \uB530\uB77C \uBD84\uB958 \uB41C \uCFE0\uD0A4\uB294 \uC6F9 \uC0AC\uC774\uD2B8\uC758 \uAE30\uBCF8\uC801\uC778 \uAE30\uB2A5\uC744 \uC218\uD589\uD558\uB294 \uB370 \uD544\uC218\uC801\uC774\uBBC0\uB85C \uBE0C\uB77C\uC6B0\uC800\uC5D0 \uC800\uC7A5\uB429\uB2C8\uB2E4.",
    "v06.reason": "Reason / \uC99D\uAC70 \uACE0\uB824",
    "v06.bookmarked": "\uB098\uC911\uC5D0 \uC800\uC7A5",
    "v06.previewRepair": "\uBBF8\uB9AC\uBCF4\uAE30 whitespace \uC218\uB9AC",
    "v06.repairCount": "{count} \uAC12\uC774 \uBCC0\uACBD\uB429\uB2C8\uB2E4. \uC8FC\uBCC0 whitespace \uB9CC \uC81C\uAC70\uB429\uB2C8\uB2E4. \uBBF8\uB9AC\uBCF4\uAE30\uB97C \uAC80\uC0AC\uD558\uACE0 \uC801\uC6A9\uD558\uAE30 \uC804\uC5D0 \uACB0\uC815\uC744 \uC124\uBA85\uD569\uB2C8\uB2E4.",
    "v06.applyRepair": "\uAD00\uB828 \uC0C1\uD488",
    "v06.wholeProject": "\uC6D0\uBCF8 \uD544\uB4DC \u2192 \uAE30\uB85D\uB41C \uC774\uD574 \u2192 \uAC00\uB2A5\uD55C \uD45C\uC900 \uD45C\uD604",
    "v06.originalField": "\uC774\uB984 *",
    "v06.recordedMeaning": "\uAE30\uB85D\uB41C \uD574\uC11D \uC0C1\uD0DC",
    "v06.mapped": "\uAE30\uB85D \uB41C Mapping; \uC99D\uAC70 \uD655\uC778",
    "v06.unmapped": "\uB2E4\uC6B4\uB85C\uB4DC",
    "v06.downloadRecipe": "reproducible \uC870\uB9AC\uBC95 \uB2E4\uC6B4\uB85C\uB4DC",
    "v06.noMatchingIssues": "\uC81C\uC548\uC774 \uD544\uD130\uC5D0 \uC77C\uCE58\uD558\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4. \uC774\uAC83\uC740 dataset\uC758 \uACFC\uD559\uC801 \uD488\uC9C8\uC744 \uC778\uC99D\uD558\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4.",
    "v06.reviewPageLimit": "\uCCAB\uBC88\uC9F8 100\uAC1C\uC758 \uC81C\uC548\uB9CC \uD45C\uC2DC\uB429\uB2C8\uB2E4. \uB2E4\uB978 \uC0AC\uB78C\uC744 \uAC80\uD1A0\uD558\uAE30 \uC704\uD558\uC5EC \uC885\uB958\uC5D0 \uC758\uD558\uC5EC \uC5EC\uACFC\uAE30; \uC644\uC804\uD55C \uBD84\uC11D\uC740 \uC720\uD6A8\uD569\uB2C8\uB2E4.",
    "v06.reviewHistory": "\uD68C\uC0AC\uC5F0\uD601",
    "v06.saved": "\uB098\uC911\uC5D0 \uC800\uC7A5 \uBC0F \uC791\uC5C5 \uB178\uD2B8",
    "v06.privateNotes": "\uC791\uC5C5 \uB178\uD2B8\uC640 \uCC45\uAC08\uD53C\uB294 \uACFC\uD559\uC801\uC778 \uBA54\uD0C0\uB370\uC774\uD130\uC5D0\uC11C \uBD84\uB9AC\uB418\uB294 \uC9C0\uC5ED \uD45C\uAE30\uC785\uB2C8\uB2E4. \uADF8\uB4E4\uC740 \uACFC\uD559\uC801 \uC218\uCD9C\uC5D0 \uD3EC\uD568\uB418\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4. \uBC31\uC5C5\uC5D0 \uB300\uD574 \uBCC4\uB3C4\uB85C \uB2E4\uC6B4\uB85C\uB4DC\uD558\uC2ED\uC2DC\uC624.",
    "v06.workingNote": "\uD68C\uC0AC \uC18C\uAC1C",
    "v06.addNote": "\uC791\uC5C5 \uB178\uD2B8 \uCD94\uAC00",
    "v06.exportNotes": "\uB85C\uCEEC \uC791\uC5C5 \uD560\uB2F9",
    "v06.why.name": "\uD544\uB4DC \uC774\uB984\uC740 \uC77C\uBC18\uC801\uC778 \uC5F0\uAD6C \uC6A9\uC5B4\uC640 \uC720\uC0AC\uD569\uB2C8\uB2E4. \uC774 \uC774\uB984 \uAE30\uBC18 \uADDC\uCE59\uC740 \uACFC\uD559\uC801 \uC758\uBBF8\uB97C \uC124\uC815\uD560 \uC218 \uC5C6\uC73C\uBA70 \uAC12\uC774 \uAC00\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4.",
    "v06.why.unknown": "\uBC1C\uACAC\uB418\uC9C0 \uC54A\uC740 \uD544\uB4DC \uC758\uBBF8\uAC00 \uC5C6\uC2B5\uB2C8\uB2E4. Surviving \uBB38\uC11C\uB294 \uB3C4\uC6C0\uC774 \uB420 \uC218 \uC788\uC2B5\uB2C8\uB2E4. \uC774 \uC54C \uC218\uC5C6\uB294 \uAC83\uC740 \uCD94\uCE21\uBCF4\uB2E4 \uB354 \uC548\uC804\uD569\uB2C8\uB2E4.",
    "v06.why.conflict": "\uAE30\uB85D\uB41C \uD574\uC11D\uC740 \uAC08\uB4F1\uC785\uB2C8\uB2E4. \uC790\uB3D9\uC801\uC73C\uB85C \uC120\uD0DD \uBCF4\uB2E4\uB294 \uB208\uC5D0 \uBCF4\uC774\uB294 \uC99D\uAC70\uB97C \uC774\uD574\uD558\uC2ED\uC2DC\uC624.",
    "v06.why.mapping": "\uD655\uC778 \uB41C \uD544\uB4DC \uC815\uC758\uC5D0\uB294 \uAE30\uB85D \uB41C \uD45C\uC900 \uB9E4\uD551\uC774 \uC5C6\uC2B5\uB2C8\uB2E4. \uC774\uB984\uC740\uC774 \uD6C4\uBCF4\uB97C \uC81C\uC548\uD569\uB2C8\uB2E4. \uC2E4\uC81C \uC758\uBBF8\uC640 \uD14C\uC774\uBE14 \uAD6C\uC870\uB97C \uBA3C\uC800 \uD655\uC778\uD558\uC2ED\uC2DC\uC624.",
    "v06.why.trim": "\uC77C\uBD80 \uC0D8\uD50C \uAC12\uC740 \uC8FC\uBCC0 whitespace\uB97C \uD3EC\uD568\uD569\uB2C8\uB2E4. \uC774 \uAE30\uACC4 \uC218\uB9AC\uB97C \uC801\uC6A9\uD558\uAE30 \uC804\uC5D0 \uC804\uCCB4 \uD14C\uC774\uBE14 \uBBF8\uB9AC\uBCF4\uAE30\uAC00 \uD544\uC694\uD569\uB2C8\uB2E4.",
    "v06.why.missing": "\uC774 \uB9AC\uD130\uB7F4 \uD1A0\uD070\uC740 \uB204\uB77D\uAC12 \uADDC\uCE59\uACFC \uC720\uC0AC\uD569\uB2C8\uB2E4. \uADF8\uB4E4\uC740 \uC2E4\uC81C \uCE21\uC815 \uB610\uB294 \uCF54\uB4DC\uAC00 \uB420 \uC218\uB3C4 \uC788\uC2B5\uB2C8\uB2E4. \uC99D\uAC70\uC5C6\uC774 \uBCC0\uD658\uD558\uC9C0 \uB9C8\uC2ED\uC2DC\uC624.",
    "v06.why.date": "\uC0D8\uD50C\uB41C \uB0A0\uC9DC\uB294 \uC77C \uCCAB\uC9F8\uC640 \uB2EC \uCCAB \uBC88\uC9F8 \uB3C5\uC11C\uB97C \uBAA8\uB450 \uD5C8\uC6A9\uD569\uB2C8\uB2E4. 2 \uC790\uB9AC \uC218 \uB144\uC740 \uB610\uD55C \uC138\uAE30\uC5D0 \uB300\uD55C \uC99D\uAC70\uAC00 \uD544\uC694\uD569\uB2C8\uB2E4. \uC791\uC5C5 \uBCA4\uCE58\uB294 \uC790\uB3D9\uC73C\uB85C \uC120\uD0DD\uD560 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4.",
    "v06.why.unit": "\uC5F4 \uC774\uB984 suffix\uB294 \uB2E8\uC704\uB97C \uB2EE\uC2B5\uB2C8\uB2E4. \uADF8\uAC83\uC740 \uC774\uB984\uC5D0\uC11C \uBC29\uD574\uC774\uACE0, \uCE21\uC815 \uCEE8\uD14D\uC2A4\uD2B8\uB97C \uD655\uC778\uD558\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4.",
    "v06.why.coordinate": "\uD544\uB4DC \uC774\uB984\uC740 \uC88C\uD45C \uCD95\uC744 \uB2EE\uC558\uB2E4. datum\uACFC \uC88C\uD45C \uCC38\uC870 \uC2DC\uC2A4\uD15C\uC740 \uBB38\uC11C\uD654\uB418\uC9C0 \uC54A\uB294 \uB0A8\uC544\uC788\uB2E4.",
    "v06.why.taxonomy": "\uC774 \uD544\uB4DC\uB294 taxon \uC774\uB984 \uB610\uB294 \uCF54\uB4DC\uB97C \uAE30\uB85D\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4. \uC5ED\uC0AC\uC801\uC778 \uC774\uB984\uC740 \uB9AC\uD130\uB7F4\uC744 \uC720\uC9C0; \uD604\uC7AC \uC774\uB984 \uC870\uD68C\uB294 \uBA85\uC2DC\uB41C \uAC80\uD1A0\uC640 \uC785\uC99D\uC744 \uC694\uAD6C\uD569\uB2C8\uB2E4.",
    "v06.why.relationship": "2\uAC1C\uC758 \uBD84\uC57C\uC5D0\uB294 \uC815\uC0C1\uC801\uC778 \uC774\uB984\uACFC \uACFC\uC789 \uAC04\uC0C9\uD55C \uAC12\uC744 \uB9E4\uACBC\uC2B5\uB2C8\uB2E4. \uBD80\uBAA8 \uACE0\uC720, cardinality, \uC77C\uCE58\uD55C \uCC38\uACE0 \uBC0F \uC9C4\uC9DC \uACFC\uD559\uC801\uC778 \uC5F0\uACB0\uC744 \uAC80\uD1A0\uD558\uC2ED\uC2DC\uC624.",
    "v06.why.codebook": "\uD14C\uC774\uBE14 \uC774\uB984\uC740 \uCF54\uBD81\uACFC \uC720\uC0AC\uD569\uB2C8\uB2E4. \uCCAB \uBC88\uC9F8 \uB450 \uD544\uB4DC\uB294 \uD6C4\uBCF4 \uCF54\uB4DC\uC640 \uC758\uBBF8\uB85C \uD45C\uC2DC\uB429\uB2C8\uB2E4. \uC774\uAC83\uC740 \uD655\uC778 \uB41C \uC0AC\uC804\uC774 \uC544\uB2D9\uB2C8\uB2E4. Conflicting \uC815\uC758\uB294 \uB208\uC5D0 \uB0A8\uC544 \uC788\uC2B5\uB2C8\uB2E4.",
    "v06.why.metadata": "Project context\uB294 \uB204\uB77D\uB418\uAC70\uB098 unconfirmed \uC124\uBA85\uC785\uB2C8\uB2E4. \uC99D\uAC70\uB97C \uC0DD\uC874\uD558\uB294 \uAC83\uC740 \uC9C0\uC6D0\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4.",
    "v06.why.privacy": "\uC88C\uD45C\uACC4\uB294 \uBBFC\uAC10\uD55C \uC704\uCE58\uB97C \uB178\uCD9C\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4. \uACF5\uC720\uD558\uAE30 \uC804\uC5D0 \uACF5\uACF5 \uC218\uCD9C \uCDE8\uAE09\uC744 \uAC80\uD1A0\uD558\uC2ED\uC2DC\uC624; \uC774 \uC704\uCE58\uAC00 \uACFC\uBBFC\uD558\uB2E4\uB294 \uAC83\uC744 \uC124\uCE58\uD558\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4.",
