    "v0610.check.identifiers": "\uC2DD\uBCC4\uC790 \uD6C4\uBCF4\uC790 \uD655\uC778",
    "v0610.finding.ambiguousDate": "{count} sampled date-like \uAC12\uC740 day/month \uD574\uC11D\uC744 \uACC4\uC0B0\uD569\uB2C8\uB2E4.",
    "v0610.finding.coordinateRange": "{count} \uC0D8\uD50C \uAC12\uC740 angular-coordinate \uD6C4\uBCF4\uC790\uB85C \uAC80\uD1A0\uD574\uC57C\uD569\uB2C8\uB2E4.",
    "v0610.finding.identifierRepeat": "{count} \uC0D8\uD50C\uB9C1\uB41C \uBB38\uD559 \uC2DD\uBCC4\uC790 \uD6C4\uBCF4 \uBC18\uBCF5; \uB3C5\uD2B9\uC131 \uBC0F \uC815\uCCB4\uC131\uC740 \uAC00\uC815\uB418\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4.",
    "v0610.finding.identifierBlank": "{count} \uC0D8\uD50C \uC2DD\uBCC4\uC790 \uD6C4\uBCF4\uC790\uB294 \uACF5\uBC31\uC785\uB2C8\uB2E4; \uD544\uC218 \uC0AC\uD56D\uC740 \uAC00\uC815\uB418\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4.",
    "v0610.wizard": "\uC218\uC785 \uB9AC\uBDF0 \uC2A4\uD0C0\uC77C",
    "v0610.profile": "workspace \uACBD\uD5D8 \uB530\uB974\uAE30",
    "v0610.guided": "Guided \uD30C\uC77C \uAC80\uC0C9",
    "v0610.technical": "\uAE30\uC220 \uB2E8\uC77C \uD30C\uC77C \uB9AC\uBDF0",
    "v0610.technicalDetails": "\uAE30\uBCF8\uC801\uC73C\uB85C \uAE30\uC220 \uC18C\uC2A4 \uC138\uBD80 \uC0AC\uD56D \uD655\uC7A5",
    "v0610.remember": "\uC131\uACF5\uC801\uC778 delimited-text \uD30C\uC2F1 \uC120\uD0DD \uAE30\uC5B5\uD558\uAE30",
    "v0610.rememberSafety": "\uC778\uCF54\uB529\uC744 \uAE30\uC5B5, delimiter \uBC0F \uD5E4\uB354 \uD589\uC740 \uC131\uACF5\uC801\uC778 \uD5CC\uC2E0\uC801\uC778 delimited-text \uAC00\uC838 \uC624\uAE30 \uD6C4\uB9CC. \uD63C\uD569 \uBC30\uCE58 \uC694\uB9AC\uBC95\uC740 \uAE30\uC5B5\uB418\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4. \uACE0\uC815 \uD3ED \uACBD\uACC4 \uBC0F \uACFC\uD559 \uCEE8\uBCA4\uC158\uC740 \uAE00\uB85C\uBC8C \uAE30\uBCF8\uC73C\uB85C \uC800\uC7A5\uB418\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4.",
    "v0610.header": "\uAE30\uBCF8 \uD5E4\uB354 \uD589",
    "v0610.headerHelp": "\uD5E4\uB354 \uD589 1\u20131,000 \uC0C8 delimited-text \uAC00\uC838 \uC624\uAE30\uC5D0 \uC801\uC6A9\uD569\uB2C8\uB2E4. \uAC01 \uBBF8\uB9AC\uBCF4\uAE30\uB294\uC774 \uC120\uD0DD\uC744 \uBB34\uC2DC\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4.",
    "v0610.integrityAlways": "\uC18C\uC2A4 \uBB34\uACB0\uC131 \uAC80\uC0AC\uB294 \uD56D\uC0C1 \uC694\uAD6C\uB418\uACE0 \uBE44\uD65C\uC131\uD654 \uB420 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4. \uC774 \uC635\uC158 \uC124\uC815\uC740 \uBCF4\uCDA9 \uC218\uC785 \uC2EC\uC0AC\uC5D0\uB9CC \uC801\uC6A9\uB429\uB2C8\uB2E4.",
    "v0610.detailsSafety": "Beginners use guided discovery by default. \uAE30\uC220\uC801\uC778 \uB9AC\uBDF0\uB294 \uBA85\uC2DC\uB41C \uD658\uACBD\uC774\uBA70, \uD504\uB85C\uC81D\uD2B8 \uB370\uC774\uD130\uB97C \uBCC0\uACBD\uD558\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4.",
    "v0610.importTechnicalDetails": "\uAE30\uBCF8\uC801\uC73C\uB85C \uAE30\uC220 \uC18C\uC2A4 \uC138\uBD80 \uC0AC\uD56D \uD655\uC7A5",
    "v0610.rememberImportChoices": "\uC131\uACF5\uC801\uC778 delimited-text \uD30C\uC2F1 \uC120\uD0DD \uAE30\uC5B5\uD558\uAE30",
    "v0610.importCheckDates": "Flag ambiguous \uB0A0\uC9DC",
    "v0610.importCheckCoordinates": "Flag suspicious \uC88C\uD45C \uD6C4\uBCF4",
    "v0610.importCheckIdentifiers": "\uC2DD\uBCC4\uC790 \uD6C4\uBCF4\uC790 \uD655\uC778",
    "v0611.invalidTrace": "\uAE30\uB85D \uB41C \uD30C\uC0DD \uB9C1\uD06C\uB294 \uC644\uC804\uD558\uAC70\uB098 \uC0AC\uC774\uD074\uB9C1\uC785\uB2C8\uB2E4. \uBE44\uAD50\uB294\uC774 \uD544\uB4DC\uB97C \uC548\uC804\uD558\uAC8C \uCD94\uC801 \uD560 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4. \uC800\uC7A5\uB41C \uC694\uB9AC\uBC95\uACFC \uC6D0\uBCF8 \uC18C\uC2A4\uB97C \uAC80\uD1A0\uD558\uC2ED\uC2DC\uC624.",
    "v0611.safety": "\uBB38\uD559\uC758 \uC77D\uAE30 \uC804\uC6A9 \uBE44\uAD50 \uAE30\uB85D, \uC791\uC5C5 \uBC0F \uAC80\uD1A0 \uB41C \uD45C\uD604. \uD589 \uBC88\uD638\uB294 \uC6D0\uB798 \uB370\uC774\uD130 \uB808\uCF54\uB4DC\uB97C \uC2DD\uBCC4, \uBB3C\uB9AC\uC801 \uD30C\uC77C \uB77C\uC778\uC774 \uC544\uB2D9\uB2C8\uB2E4. \uAE30\uC220 \uB9E4\uD551\uC740 \uAE30\uB85D \uB41C \uAC80\uD1A0 \uC0C1\uD0DC\uB97C \uC720\uC9C0; \uC774 \uC804\uB9DD\uC740 \uACFC\uD559\uC801 \uD3C9\uB4F1 \uB610\uB294 \uD45C\uC900 \uC900\uC218\uB97C \uC99D\uBA85\uD558\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4.",
    "v0611.mapping": "\uAE30\uC220\uC801\uC778 mapping",
    "v0611.noMapping": "\uC9C0\uB3C4 \uD45C\uC2DC",
    "v0611.lineage": "\uAE30\uB85D\uB41C \uC785\uB825 \uBC0F \uB9AC\uBDF0 lineage",
    "v0611.operation": "\uAE30\uB85D\uB41C \uAC00\uB3D9",
    "v0611.review": "\uC791\uC131\uC790 \uBC0F \uD569\uB9AC\uC801",
    "v0611.legacyPolicy": "\uC5ED\uC0AC \uACB8\uC6A9\uC131 \uC7AC\uC0DD: \uC774 \uAC00\uB3D9\uC740 \uC774\uC804 \uB179\uC774\uB294 outcomes\uB97C \uC804\uD30C\uD558\uC9C0 \uC54A\uACE0 \uB9AC\uD130\uC758 \uC785\uB825\uC744 \uC720\uC9C0\uD569\uB2C8\uB2E4. \uC0C8\uB85C\uC6B4 \uACFC\uD559\uC801\uC778 \uD655\uC778\uC774 \uC544\uB2D9\uB2C8\uB2E4.",
    "v0611.propagationPolicy": "\uD574\uACB0 \uBC0F \uCDA9\uB3CC \uC5C5\uC2A4\uD2B8\uB9BC \uACB0\uACFC \uBCC0\uD658\uC5C6\uC774 \uC55E\uC73C\uB85C \uC218\uD589\uB41C\uB2E4.",
    "v0611.rowOutcome": "\uD589 outcome",
    "v0611.fieldReview": "Field \uD574\uC11D \uAC80\uD1A0",
    "v0612.title": "\uAC80\uD1A0 \uB41C \uD0A4\uB85C \uB450 \uAC1C\uC758 \uD14C\uC774\uBE14 \uBE44\uAD50",
    "v0612.needTables": "\uC801\uC5B4\uB3C4 \uB450 \uAC1C\uC758 \uD14C\uC774\uBE14\uC744 \uAC00\uC838\uC640 \uB9AC\uD130 \uB808\uCF54\uB4DC\uB97C \uBE44\uAD50\uD569\uB2C8\uB2E4.",
    "v0612.safety": "\uC774 \uC77D\uAE30 \uC804\uC6A9 \uBE44\uAD50\uB294 \uD14C\uC774\uBE14\uC744 \uBCD1\uD569\uD558\uC9C0 \uC54A\uAC70\uB098 \uACFC\uD559\uC801\uC778 equivalence\uB97C \uD655\uC778\uD558\uC2ED\uC2DC\uC624. \uD0A4\uC640 \uD544\uB4DC\uB97C \uBA85\uC2DC\uC801\uC73C\uB85C \uC120\uD0DD\uD558\uC2ED\uC2DC\uC624.",
    "v0612.leftTable": "\uC67C\uCABD \uD14C\uC774\uBE14",
    "v0612.rightTable": "\uC624\uB978\uCABD \uD14C\uC774\uBE14",
    "v0612.leftField": "\uC67C\uCABD \uC601\uC5ED",
    "v0612.rightField": "\uD68C\uC0AC\uC5F0\uD601",
    "v0612.chooseField": "\uC120\uD0DD\uD558\uAE30",
    "v0612.keys": "\uC8FC\uBB38\uB41C \uC5F4\uC1E0 \uC30D",
    "v0612.fields": "\uBE44\uAD50\uD558\uAE30",
    "v0612.keySafety": "\uB3D9\uC77C\uD55C \uB9AC\uD2C0 \uD0A4 \uC77C\uCE58\uB9CC. \uBE48 \uD0A4 \uAD6C\uC131 \uC694\uC18C\uB294 \uC5F0\uACB0\uB418\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4. \uC911\uBCF5 \uD0A4\uB294 \uACB0\uCF54 \uBC18\uB300\uB97C \uC120\uD0DD\uD558\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4.",
    "v0612.fieldSafety": "\uBE44\uAD50\uD560 \uC218 \uC788\uB294 \uAE30\uB85D\uB41C \uAC12\uC774 \uC788\uB294 \uD544\uB4DC \uC30D\uC744 \uC120\uD0DD\uD558\uC2ED\uC2DC\uC624. \uAC12\uC774 \uBCC0\uD658\uB418\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4.",
    "v0612.removePair": "\uC30D\uC744 \uC81C\uAC70",
    "v0612.addKey": "\uD0A4 \uC30D \uCD94\uAC00",
    "v0612.addField": "\uD544\uB4DC \uC30D \uCD94\uAC00",
