    "v0612.reason": "\uC774 \uC30D\uC744 \uC704\uD55C Reason",
    "v0612.confirm": "\uB098\uB294\uC774 \uB9AC\uD130 \uD0A4\uC640 \uD544\uB4DC \uC30D\uC744 \uAC80\uD1A0\uD588\uB2E4.",
    "v0612.limits": "\uD14C\uC774\uBE14 \uB2F9 100,000\uAE4C\uC9C0 \uAE30\uB85D \uC9C0\uC6D0, 5\uAC1C\uC758 \uC5F4\uC1E0 \uC30D, 100\uAC1C\uC758 \uBD84\uC57C \uC30D \uBC0F 2\uBC31\uB9CC\uAC1C\uC758 \uC120\uD0DD\uB41C \uC138\uD3EC\uB97C \uC644\uB8CC\uD558\uC2ED\uC2DC\uC624. \uB300\uD615 \uBE44\uAD50\uB294 \uD45C\uBCF8 \uCD94\uCD9C \uC5C6\uC774 \uAC70\uC808\uB429\uB2C8\uB2E4.",
    "v0612.preview": "\uC18C\uC2A4\uC640 \uBE44\uAD50",
    "v0612.checking": "\uC6D0\uBCF8 \uC18C\uC2A4 \uBC0F \uD604\uC7AC \uD504\uB85C\uC81D\uD2B8\uB97C \uD655\uC778 ...",
    "v0612.ready": "\uBE44\uAD50 \uC900\uBE44. \uC18C\uC2A4, \uC791\uC5C5 \uAC12 \uB610\uB294 \uBA54\uD0C0\uB370\uC774\uD130\uAC00 \uBCC0\uACBD\uB418\uC5C8\uC2B5\uB2C8\uB2E4.",
    "v0612.resultTitle": "\uB9AC\uD130 \uBE44\uAD50 \uACB0\uACFC",
    "v0612.countSafety": "Ambiguous counts\uB294 \uC591\uCABD\uC5D0 \uAC01 unpaired \uAE30\uB85D\uC744 \uD3EC\uD568\uD569\uB2C8\uB2E4. \uB3D9\uB4F1\uD55C \uAC12\uC740 \uACFC\uD559\uC801\uC778 equivalence\uB97C \uC124\uCE58\uD558\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4.",
    "v0612.duplicates": "\uC911\uBCF5 \uD0A4 \uADF8\uB8F9: \uC67C\uCABD {left}; \uAD8C\uB9AC {right}\xB7",
    "v0612.filter": "\uACB0\uACFC\uBCF4\uAE30",
    "v0612.all": "\uBAA8\uB4E0 \uACB0\uACFC",
    "v0612.previewBounds": "\uBBF8\uB9AC\uBCF4\uAE30\uB294 \uD398\uC774\uC9C0 \uB2F9 25 \uB808\uCF54\uB4DC\uC640 \uAC12 \uB2F9 512 \uBB38\uC790\uAE4C\uC9C0 \uBCF4\uC5EC\uC90D\uB2C8\uB2E4. \uC77C\uCE58\uB294 \uC644\uC804\uD55C \uAC12\uC744 \uC0AC\uC6A9\uD569\uB2C8\uB2E4.",
