    "v0612.differentValue": "\uB2E4\uB978 \uB9AC\uD130 \uAC12",
    "v0612.download": "\uAC1C\uC778 \uBE44\uAD50 \uBCF4\uACE0\uC11C \uB2E4\uC6B4\uB85C\uB4DC",
    "v0612.privateReport": "\uBCF4\uACE0\uC11C\uC5D0\uB294 \uC18C\uC2A4 \uD574\uC2DC, \uAC80\uD1A0 \uB41C \uC30D, \uD544\uB4DC \uC815\uC758, \uC9C0\uBB38 \uBC0F \uBAA8\uB4E0 \uB808\uCF54\uB4DC \uACB0\uACFC\uAC00 \uD3EC\uD568\uB418\uC5B4 \uC788\uC2B5\uB2C8\uB2E4. \uACF5\uC720\uD558\uAE30 \uC804\uC5D0 \uADF8\uAC83\uC744 \uAC80\uD1A0\uD558\uC2ED\uC2DC\uC624 : \uC774\uB984 \uBC0F \uB9AC\uBDF0 \uB178\uD2B8\uB294 \uBBFC\uAC10 \uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4.",
    "v0612.recipe": "\uBE44\uAD50 \uBC0F \uAC80\uC99D",
    "v0612.recordsInDownload": "\uBAA8\uB4E0 \uB808\uCF54\uB4DC\uB294 \uB2E4\uC6B4\uB85C\uB4DC \uB41C \uBCF4\uACE0\uC11C\uC5D0 \uD3EC\uD568\uB418\uC5B4 \uC788\uC2B5\uB2C8\uB2E4.",
    "v0612.status.equal": "Equal \uB9AC\uD130 \uAC12",
    "v0612.status.different": "\uB2E4\uB978 \uB9AC\uD130 \uAC12",
