// web/i18n.mjs
for (const catalog of Object.values(catalogs)) Object.assign(catalog, workstationCopy, structuralCopy, experienceCopy, helpCopy, studioCopy, knowledgeCopy, workspaceCopy, tutorialCopy, practiceCopy);
var labels = new Map(Object.entries(catalogs.en).map(([key, text]) => [text, key]));
var placeholders = (text) => [...String(text).matchAll(/\{([A-Za-z][A-Za-z0-9_]*)\}/g)].map((x) => x[1]).sort();
var escapePattern = (value) => value.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
var messagePatterns = Object.entries(catalogs.en).filter(([, text]) => placeholders(text).length && text.replace(/\{[^}]+\}/g, "").length >= 4).map(([key, text]) => {
  const names = [];
  let pattern = "", start = 0;
  for (const match of text.matchAll(/\{([A-Za-z][A-Za-z0-9_]*)\}/g)) {
    pattern += escapePattern(text.slice(start, match.index)) + "([\\s\\S]*?)";
    names.push(match[1]);
    start = match.index + match[0].length;
  }
  return { key, names, length: text.length, pattern: new RegExp("^" + pattern + escapePattern(text.slice(start)) + "$") };
}).sort((a, b) => b.length - a.length);

